//! Core geometry primitives: points, rectangles, paths and the low level
//! numeric predicates used by the clipping engine and the offsetter.
//!
//! All rounding here mirrors the reference C++ implementation exactly:
//! integer points built from floating point values round half away from zero
//! (`std::round`), while the sweep line uses round half to even
//! (`std::nearbyint`) and segment intersections truncate toward zero
//! (`static_cast<int64_t>`).

pub const MAX_COORD: i64 = i64::MAX / 4;
pub const MIN_COORD: i64 = -MAX_COORD;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    #[inline]
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// `Point64(double, double)` - the C++ constructor rounds with std::round.
    #[inline]
    pub fn from_f64(x: f64, y: f64) -> Self {
        Point64 {
            x: round_half_away(x) as i64,
            y: round_half_away(y) as i64,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    #[inline]
    pub fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }
    #[inline]
    pub fn negate(&mut self) {
        self.x = -self.x;
        self.y = -self.y;
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    #[inline]
    pub fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 {
            left,
            top,
            right,
            bottom,
        }
    }
    /// Rect64(false) in C++ - an "invalid" (inverted) rectangle.
    #[inline]
    pub fn invalid() -> Self {
        Rect64 {
            left: MAX_COORD,
            top: MAX_COORD,
            right: MIN_COORD,
            bottom: MIN_COORD,
        }
    }
    #[inline]
    pub fn zero() -> Self {
        Rect64 {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
        }
    }
    #[inline]
    pub fn width(&self) -> i64 {
        self.right - self.left
    }
    #[inline]
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }
    #[inline]
    pub fn contains_rect(&self, rec: &Rect64) -> bool {
        rec.left >= self.left && rec.right <= self.right && rec.top >= self.top
            && rec.bottom <= self.bottom
    }
    #[inline]
    pub fn contains_pt(&self, pt: &Point64) -> bool {
        pt.x > self.left && pt.x < self.right && pt.y > self.top && pt.y < self.bottom
    }
    #[inline]
    pub fn intersects(&self, rec: &Rect64) -> bool {
        (self.left.max(rec.left) <= self.right.min(rec.right))
            && (self.top.max(rec.top) <= self.bottom.min(rec.bottom))
    }
    #[inline]
    pub fn mid_point(&self) -> Point64 {
        Point64::new((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }
}

/// std::round: halfway cases away from zero.
#[inline]
pub fn round_half_away(x: f64) -> f64 {
    x.round()
}

/// std::nearbyint with the default rounding mode: halfway cases to even.
#[inline]
pub fn nearbyint(x: f64) -> f64 {
    let f = x.floor();
    let diff = x - f;
    if diff > 0.5 {
        f + 1.0
    } else if diff < 0.5 {
        f
    } else if f % 2.0 == 0.0 {
        f
    } else {
        f + 1.0
    }
}

#[inline]
pub fn sqr(v: f64) -> f64 {
    v * v
}

#[inline]
pub fn cross_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.y - pt2.y) as f64)
        - ((pt2.y - pt1.y) as f64) * ((pt3.x - pt2.x) as f64)
}

#[inline]
pub fn cross_product_d(vec1: PointD, vec2: PointD) -> f64 {
    vec1.y * vec2.x - vec2.y * vec1.x
}

#[inline]
pub fn dot_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    ((pt2.x - pt1.x) as f64) * ((pt3.x - pt2.x) as f64)
        + ((pt2.y - pt1.y) as f64) * ((pt3.y - pt2.y) as f64)
}

#[inline]
pub fn dot_product_d(vec1: PointD, vec2: PointD) -> f64 {
    vec1.x * vec2.x + vec1.y * vec2.y
}

/// Exact test for a*b == c*d (the C++ code uses 128 bit intermediates).
#[inline]
pub fn products_are_equal(a: i64, b: i64, c: i64, d: i64) -> bool {
    (a as i128) * (b as i128) == (c as i128) * (d as i128)
}

#[inline]
pub fn is_collinear(pt1: Point64, shared_pt: Point64, pt2: Point64) -> bool {
    let a = shared_pt.x - pt1.x;
    let b = pt2.y - shared_pt.y;
    let c = shared_pt.y - pt1.y;
    let d = pt2.x - shared_pt.x;
    products_are_equal(a, b, c, d)
}

/// Exact sign of the cross product (-1, 0 or 1).
#[inline]
pub fn cross_product_sign(pt1: Point64, pt2: Point64, pt3: Point64) -> i32 {
