    let dx = (seg2.x - seg1.x) as f64;
    let dy = (seg2.y - seg1.y) as f64;
    let mut q = ((offset_pt.x - seg1.x) as f64 * dx + (offset_pt.y - seg1.y) as f64 * dy)
