//! Core geometry primitives: points, rectangles, paths and the low level
//! numeric predicates used by the clipping engine and the offsetter.
//!
//! All rounding here mirrors the reference C++ implementation exactly:
//! integer points built from floating point values round half away from zero
//! (`std::round`), while the sweep line uses round half to even
//! (`std::nearbyint`) and segment intersections truncate toward zero
//! (`static_cast<int64_t>`).

pub const MAX_COORD: i64 = i64::MAX / 4;
pub const MIN_COORD: i64 = -MAX_COORD;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    #[inline]
    pub fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// `Point64(double, double)` - the C++ constructor rounds with std::round.
    #[inline]
    pub fn from_f64(x: f64, y: f64) -> Self {
        Point64 {
            x: round_half_away(x) as i64,
            y: round_half_away(y) as i64,
        }
    }
}

