pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    #[inline]
    pub fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }
    #[inline]
    pub fn negate(&mut self) {
        self.x = -self.x;
        self.y = -self.y;
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    #[inline]
    pub fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 {
            left,
            top,
            right,
            bottom,
        }
    }
    /// Rect64(false) in C++ - an "invalid" (inverted) rectangle.
    #[inline]
    pub fn invalid() -> Self {
        Rect64 {
            left: MAX_COORD,
            top: MAX_COORD,
            right: MIN_COORD,
            bottom: MIN_COORD,
        }
    }
    #[inline]
    pub fn zero() -> Self {
        Rect64 {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
        }
    }
    #[inline]
    pub fn width(&self) -> i64 {
        self.right - self.left
    }
    #[inline]
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }
    #[inline]
    pub fn contains_rect(&self, rec: &Rect64) -> bool {
        rec.left >= self.left && rec.right <= self.right && rec.top >= self.top
            && rec.bottom <= self.bottom
    }
    #[inline]
    pub fn contains_pt(&self, pt: &Point64) -> bool {
        pt.x > self.left && pt.x < self.right && pt.y > self.top && pt.y < self.bottom
    }
    #[inline]
    pub fn intersects(&self, rec: &Rect64) -> bool {
        (self.left.max(rec.left) <= self.right.min(rec.right))
            && (self.top.max(rec.top) <= self.bottom.min(rec.bottom))
    }
    #[inline]
    pub fn mid_point(&self) -> Point64 {
        Point64::new((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }
}

/// std::round: halfway cases away from zero.
#[inline]
pub fn round_half_away(x: f64) -> f64 {
    x.round()
}

/// std::nearbyint with the default rounding mode: halfway cases to even.
#[inline]
pub fn nearbyint(x: f64) -> f64 {
    let f = x.floor();
    let diff = x - f;
    if diff > 0.5 {
        f + 1.0
    } else if diff < 0.5 {
        f
    } else if f % 2.0 == 0.0 {
        f
    } else {
        f + 1.0
    }
}

