//! libstdc++ compatible sort routines.
//!
//! `std::sort` is an introsort and is *not* stable, so the order of equal
//! elements depends on the exact algorithm.  The clipping engine sorts its
//! intersection list with `std::sort`, and ties there are common, so the
//! libstdc++ implementation is reproduced here verbatim.

const S_THRESHOLD: usize = 16;

fn lg(mut n: usize) -> u32 {
    // std::__lg(n) == floor(log2(n))
    let mut k = 0u32;
    while n > 1 {
        n >>= 1;
        k += 1;
    }
    k
}

/// std::sort(first, last, comp)
pub fn std_sort<T, F: Fn(&T, &T) -> bool>(v: &mut [T], comp: &F) {
    if !v.is_empty() {
        let depth = lg(v.len()) * 2;
        introsort_loop(v, 0, v.len(), depth as i64, comp);
        final_insertion_sort(v, comp);
    }
}

fn introsort_loop<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    mut last: usize,
    mut depth_limit: i64,
    comp: &F,
) {
    while last - first > S_THRESHOLD {
        if depth_limit == 0 {
            partial_sort(v, first, last, last, comp);
            return;
        }
        depth_limit -= 1;
        let cut = unguarded_partition_pivot(v, first, last, comp);
        introsort_loop(v, cut, last, depth_limit, comp);
        last = cut;
    }
}

fn unguarded_partition_pivot<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    last: usize,
    comp: &F,
) -> usize {
    let mid = first + (last - first) / 2;
    move_median_to_first(v, first, first + 1, mid, last - 1, comp);
    unguarded_partition(v, first + 1, last, first, comp)
}

fn move_median_to_first<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    result: usize,
    a: usize,
    b: usize,
    c: usize,
    comp: &F,
) {
    if comp(&v[a], &v[b]) {
        if comp(&v[b], &v[c]) {
            v.swap(result, b);
        } else if comp(&v[a], &v[c]) {
            v.swap(result, c);
        } else {
            v.swap(result, a);
        }
    } else if comp(&v[a], &v[c]) {
        v.swap(result, a);
    } else if comp(&v[b], &v[c]) {
        v.swap(result, c);
    } else {
        v.swap(result, b);
    }
}

fn unguarded_partition<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    mut first: usize,
    mut last: usize,
    pivot: usize,
    comp: &F,
) -> usize {
    loop {
        while comp(&v[first], &v[pivot]) {
            first += 1;
        }
        last -= 1;
        while comp(&v[pivot], &v[last]) {
            last -= 1;
        }
        if first >= last {
            return first;
        }
        v.swap(first, last);
        first += 1;
    }
}

fn final_insertion_sort<T, F: Fn(&T, &T) -> bool>(v: &mut [T], comp: &F) {
    let len = v.len();
    if len > S_THRESHOLD {
        insertion_sort(v, 0, S_THRESHOLD, comp);
        unguarded_insertion_sort(v, S_THRESHOLD, len, comp);
    } else {
        insertion_sort(v, 0, len, comp);
    }
}

fn insertion_sort<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    last: usize,
    comp: &F,
) {
    if first == last {
        return;
    }
    for i in (first + 1)..last {
        if comp(&v[i], &v[first]) {
            // rotate v[first..=i] right by one
            v[first..=i].rotate_right(1);
        } else {
            unguarded_linear_insert(v, i, comp);
        }
    }
}

fn unguarded_insertion_sort<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    last: usize,
    comp: &F,
) {
    for i in first..last {
        unguarded_linear_insert(v, i, comp);
    }
}

fn unguarded_linear_insert<T, F: Fn(&T, &T) -> bool>(v: &mut [T], last: usize, comp: &F) {
    let mut l = last;
    while l > 0 && comp(&v[l], &v[l - 1]) {
        v.swap(l, l - 1);
        l -= 1;
    }
}

// ---- heap based partial_sort (used when introsort hits its depth limit) ----

fn partial_sort<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    middle: usize,
    last: usize,
    comp: &F,
) {
    heap_select(v, first, middle, last, comp);
    sort_heap(v, first, middle, comp);
}

fn heap_select<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    middle: usize,
    last: usize,
    comp: &F,
) {
    make_heap(v, first, middle, comp);
    for i in middle..last {
        if comp(&v[i], &v[first]) {
            pop_heap_to(v, first, middle, i, comp);
        }
    }
}

fn make_heap<T, F: Fn(&T, &T) -> bool>(v: &mut [T], first: usize, last: usize, comp: &F) {
    let len = last - first;
    if len < 2 {
        return;
    }
    let mut parent = (len - 2) / 2;
    loop {
        adjust_heap(v, first, parent, len, comp);
        if parent == 0 {
            return;
        }
        parent -= 1;
    }
}

fn adjust_heap<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    hole_index: usize,
    len: usize,
    comp: &F,
) {
    let top_index = hole_index;
    let mut hole = hole_index;
    let mut second_child = hole;
    while second_child < (len - 1) / 2 {
        second_child = 2 * (second_child + 1);
        if comp(&v[first + second_child], &v[first + second_child - 1]) {
            second_child -= 1;
        }
        v.swap(first + hole, first + second_child);
        hole = second_child;
    }
    if len % 2 == 0 && second_child == (len - 2) / 2 {
        second_child = 2 * (second_child + 1);
        v.swap(first + hole, first + second_child - 1);
        hole = second_child - 1;
    }
    // push_heap for the value now at `hole`
    push_heap(v, first, hole, top_index, comp);
}

fn push_heap<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    hole_index: usize,
    top_index: usize,
    comp: &F,
) {
    let mut hole = hole_index;
    let mut parent = if hole == 0 { 0 } else { (hole - 1) / 2 };
    while hole > top_index && comp(&v[first + parent], &v[first + hole]) {
        v.swap(first + hole, first + parent);
        hole = parent;
        if hole == 0 {
            break;
        }
        parent = (hole - 1) / 2;
    }
}

fn pop_heap_to<T, F: Fn(&T, &T) -> bool>(
    v: &mut [T],
    first: usize,
    last: usize,
    result: usize,
    comp: &F,
) {
    v.swap(first, result);
    adjust_heap(v, first, 0, last - first, comp);
}

fn sort_heap<T, F: Fn(&T, &T) -> bool>(v: &mut [T], first: usize, last: usize, comp: &F) {
    let mut l = last;
    while l - first > 1 {
        l -= 1;
        pop_heap_to(v, first, l, l, comp);
    }
}

