//! The clipping engine: a Vatti style sweep line, faithful to the reference
//! C++ implementation (v2.0.1) including its output-point bookkeeping,
//! horizontal-segment joins and post-sweep cleanup.

use crate::core::*;
use crate::stdsort::std_sort;
use std::collections::BinaryHeap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    NoClip,
    Intersection,
    Union,
    Difference,
    Xor,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PathType {
    Subject,
    Clip,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum JoinWith {
    NoJoin,
    Left,
    Right,
}

const VF_OPEN_START: u32 = 1;
const VF_OPEN_END: u32 = 2;
const VF_LOCAL_MAX: u32 = 4;
const VF_LOCAL_MIN: u32 = 8;

const NONE: usize = usize::MAX;

#[derive(Clone, Copy)]
struct Vertex {
    pt: Point64,
    next: usize,
    prev: usize,
    flags: u32,
}

#[derive(Clone, Copy)]
struct LocalMinima {
    vertex: usize,
    polytype: PathType,
    is_open: bool,
}

#[derive(Clone, Copy)]
struct OutPt {
    pt: Point64,
    next: usize,
    prev: usize,
    outrec: usize,
    horz: usize, // index into horz_seg_list_, or NONE
}

#[derive(Clone)]
struct OutRec {
    idx: usize,
    owner: usize,
    front_edge: usize,
    back_edge: usize,
    pts: usize,
    is_open: bool,
    splits: Vec<usize>,
}

#[derive(Clone, Copy)]
struct Active {
    bot: Point64,
    top: Point64,
    curr_x: i64,
    dx: f64,
    wind_dx: i32,
    wind_cnt: i32,
    wind_cnt2: i32,
    outrec: usize,
    prev_in_ael: usize,
    next_in_ael: usize,
    prev_in_sel: usize,
    next_in_sel: usize,
    jump: usize,
    vertex_top: usize,
    local_min: usize,
    is_left_bound: bool,
    join_with: JoinWith,
}

impl Active {
    fn new() -> Self {
        Active {
            bot: Point64::new(0, 0),
            top: Point64::new(0, 0),
            curr_x: 0,
            dx: 0.0,
            wind_dx: 1,
            wind_cnt: 0,
            wind_cnt2: 0,
            outrec: NONE,
            prev_in_ael: NONE,
            next_in_ael: NONE,
            prev_in_sel: NONE,
            next_in_sel: NONE,
            jump: NONE,
            vertex_top: NONE,
            local_min: NONE,
            is_left_bound: false,
            join_with: JoinWith::NoJoin,
        }
    }
}

#[derive(Clone, Copy)]
struct IntersectNode {
    pt: Point64,
    edge1: usize,
    edge2: usize,
}

#[derive(Clone, Copy)]
struct HorzSegment {
    left_op: usize,
    right_op: usize,
    left_to_right: bool,
}

#[derive(Clone, Copy)]
struct HorzJoin {
    op1: usize,
    op2: usize,
}

pub struct Clipper {
    // arenas
    vertex_list: Vec<Vertex>,
    minima_list: Vec<LocalMinima>,
    outpt_list: Vec<OutPt>,
    outrec_list: Vec<OutRec>,
    active_list: Vec<Active>,

    horz_seg_list: Vec<HorzSegment>,
    horz_join_list: Vec<HorzJoin>,
    intersect_nodes: Vec<IntersectNode>,
    scanline_list: BinaryHeap<i64>,

    current_locmin: usize,
    actives: usize,
    sel: usize,

    cliptype: ClipType,
    fillrule: FillRule,
    bot_y: i64,
    minima_list_sorted: bool,
    has_open_paths: bool,
    using_polytree: bool,
    succeeded: bool,
    preserve_collinear: bool,
    reverse_solution: bool,
}

impl Clipper {
    pub fn new() -> Self {
        Clipper {
            vertex_list: Vec::new(),
            minima_list: Vec::new(),
            outpt_list: Vec::new(),
            outrec_list: Vec::new(),
            active_list: Vec::new(),
            horz_seg_list: Vec::new(),
            horz_join_list: Vec::new(),
            intersect_nodes: Vec::new(),
            scanline_list: BinaryHeap::new(),
            current_locmin: 0,
            actives: NONE,
            sel: NONE,
            cliptype: ClipType::NoClip,
            fillrule: FillRule::EvenOdd,
            bot_y: 0,
            minima_list_sorted: false,
            has_open_paths: false,
            using_polytree: false,
            succeeded: true,
            preserve_collinear: false,
            reverse_solution: false,
        }
    }

    // ---- small accessors -------------------------------------------------

    #[inline]
    fn v(&self, i: usize) -> Vertex {
        self.vertex_list[i]
    }
    #[inline]
    fn op(&self, i: usize) -> OutPt {
        self.outpt_list[i]
    }
    #[inline]
    fn e(&self, i: usize) -> Active {
        self.active_list[i]
    }
    #[inline]
    fn lm(&self, i: usize) -> LocalMinima {
        self.minima_list[i]
    }

    #[inline]
    fn is_open(&self, e: usize) -> bool {
        self.lm(self.e(e).local_min).is_open
    }
    #[inline]
    fn is_open_end_v(&self, v: usize) -> bool {
        self.v(v).flags & (VF_OPEN_START | VF_OPEN_END) != 0
    }
    #[inline]
    fn is_open_end(&self, e: usize) -> bool {
        self.is_open(e) && self.is_open_end_v(self.e(e).vertex_top)
    }
    #[inline]
    fn is_hot_edge(&self, e: usize) -> bool {
        self.e(e).outrec != NONE
    }
    #[inline]
    fn is_joined(&self, e: usize) -> bool {
        self.e(e).join_with != JoinWith::NoJoin
    }
    #[inline]
    fn is_front(&self, e: usize) -> bool {
        self.outrec_list[self.e(e).outrec].front_edge == e
    }
    #[inline]
    fn poly_type(&self, e: usize) -> PathType {
        self.lm(self.e(e).local_min).polytype
    }
    #[inline]
    fn is_same_poly_type(&self, e1: usize, e2: usize) -> bool {
        self.poly_type(e1) == self.poly_type(e2)
    }
    #[inline]
    fn is_maxima_v(&self, v: usize) -> bool {
        self.v(v).flags & VF_LOCAL_MAX != 0
    }
    #[inline]
    fn is_maxima(&self, e: usize) -> bool {
        self.is_maxima_v(self.e(e).vertex_top)
    }
    #[inline]
    fn is_horizontal(&self, e: usize) -> bool {
        let a = self.e(e);
        a.top.y == a.bot.y
    }
    #[inline]
    fn is_heading_right_horz(&self, e: usize) -> bool {
        self.e(e).dx == -f64::MAX
    }
    #[inline]
    fn is_heading_left_horz(&self, e: usize) -> bool {
        self.e(e).dx == f64::MAX
    }
    #[inline]
    fn next_vertex(&self, e: usize) -> usize {
        let a = self.e(e);
        if a.wind_dx > 0 {
            self.v(a.vertex_top).next
        } else {
            self.v(a.vertex_top).prev
        }
    }
    /// The vertex preceding the bottom of this edge's bound.
    #[inline]
    fn prev_prev_vertex(&self, e: usize) -> usize {
        let a = self.e(e);
        if a.wind_dx > 0 {
            self.v(self.v(a.vertex_top).prev).prev
        } else {
            self.v(self.v(a.vertex_top).next).next
        }
    }

    fn set_dx(&mut self, e: usize) {
        let a = self.e(e);
        self.active_list[e].dx = get_dx(a.bot, a.top);
    }

    fn get_prev_hot_edge(&self, e: usize) -> usize {
        let mut prev = self.e(e).prev_in_ael;
        while prev != NONE && (self.is_open(prev) || !self.is_hot_edge(prev)) {
            prev = self.e(prev).prev_in_ael;
        }
        prev
    }

    fn get_maxima_pair(&self, e: usize) -> usize {
        let mut e2 = self.e(e).next_in_ael;
        while e2 != NONE {
            if self.e(e2).vertex_top == self.e(e).vertex_top {
                return e2;
            }
            e2 = self.e(e2).next_in_ael;
        }
        NONE
    }

    fn get_curr_y_maxima_vertex(&self, e: usize) -> usize {
        let a = self.e(e);
        let mut result = a.vertex_top;
        if a.wind_dx > 0 {
            while self.v(self.v(result).next).pt.y == self.v(result).pt.y {
                result = self.v(result).next;
            }
        } else {
            while self.v(self.v(result).prev).pt.y == self.v(result).pt.y {
                result = self.v(result).prev;
            }
        }
        if !self.is_maxima_v(result) {
            NONE
        } else {
            result
        }
    }

    // ---- path input ------------------------------------------------------

    pub fn add_paths(&mut self, paths: &[Path64], polytype: PathType, is_open: bool) {
        if is_open {
            self.has_open_paths = true;
        }
        self.minima_list_sorted = false;

        for path in paths {
            let v0 = self.vertex_list.len();
            let mut cnt = 0usize;
            // build a circular double linked list of vertices, skipping duplicates
            for &pt in path.iter() {
                if cnt > 0 {
                    let prev = self.vertex_list.len() - 1;
                    if self.vertex_list[prev].pt == pt {
                        continue;
                    }
                }
                self.vertex_list.push(Vertex {
                    pt,
                    next: NONE,
                    prev: NONE,
                    flags: 0,
                });
                cnt += 1;
            }
            if cnt < 2 {
                // not a valid path
                self.vertex_list.truncate(v0);
                continue;
            }
            let mut last = v0 + cnt - 1;
            if !is_open && self.vertex_list[last].pt == self.vertex_list[v0].pt {
                last -= 1;
                self.vertex_list.truncate(last + 1);
            }
            if last <= v0 {
                self.vertex_list.truncate(v0);
                continue;
            }
            for i in v0..=last {
                let n = if i == last { v0 } else { i + 1 };
                let p = if i == v0 { last } else { i - 1 };
                self.vertex_list[i].next = n;
                self.vertex_list[i].prev = p;
            }
            if !is_open && self.v(v0).next == v0 {
                self.vertex_list.truncate(v0);
                continue;
            }

            let curr_v = v0;
            let going_up;
            if is_open {
                let mut cv = self.v(curr_v).next;
                while cv != curr_v && self.v(cv).pt.y == self.v(curr_v).pt.y {
                    cv = self.v(cv).next;
                }
                going_up = self.v(cv).pt.y <= self.v(curr_v).pt.y;
                if going_up {
                    self.vertex_list[curr_v].flags = VF_OPEN_START;
                    self.add_loc_min(curr_v, polytype, true);
                } else {
                    self.vertex_list[curr_v].flags = VF_OPEN_START | VF_LOCAL_MAX;
                }
            } else {
                let mut pv = self.v(curr_v).prev;
                while pv != curr_v && self.v(pv).pt.y == self.v(curr_v).pt.y {
                    pv = self.v(pv).prev;
                }
                if pv == curr_v {
                    // only open paths can be completely flat
                    continue;
                }
                going_up = self.v(pv).pt.y > self.v(curr_v).pt.y;
            }

            let going_up0 = going_up;
            let mut going_up = going_up;
            let mut prev_v = curr_v;
            let mut vv = self.v(curr_v).next;
            while vv != curr_v {
                if self.v(vv).pt.y > self.v(prev_v).pt.y && going_up {
                    self.vertex_list[prev_v].flags |= VF_LOCAL_MAX;
                    going_up = false;
                } else if self.v(vv).pt.y < self.v(prev_v).pt.y && !going_up {
                    going_up = true;
                    self.add_loc_min(prev_v, polytype, is_open);
                }
                prev_v = vv;
                vv = self.v(vv).next;
            }

            if is_open {
                self.vertex_list[prev_v].flags |= VF_OPEN_END;
                if going_up {
                    self.vertex_list[prev_v].flags |= VF_LOCAL_MAX;
                } else {
                    self.add_loc_min(prev_v, polytype, is_open);
                }
            } else if going_up != going_up0 {
                if going_up0 {
                    self.add_loc_min(prev_v, polytype, is_open);
                } else {
                    self.vertex_list[prev_v].flags |= VF_LOCAL_MAX;
                }
            }
        }
    }

    fn add_loc_min(&mut self, vert: usize, polytype: PathType, is_open: bool) {
        // make sure the vertex is added only once
        if self.vertex_list[vert].flags & VF_LOCAL_MIN != 0 {
            return;
        }
        self.vertex_list[vert].flags |= VF_LOCAL_MIN;
        self.minima_list.push(LocalMinima {
            vertex: vert,
            polytype,
            is_open,
        });
    }

    fn reset(&mut self) {
        if !self.minima_list_sorted {
            // std::stable_sort with LocMinSorter
            let verts = &self.vertex_list;
            self.minima_list.sort_by(|a, b| {
                let pa = verts[a.vertex].pt;
                let pb = verts[b.vertex].pt;
                if pa.y != pb.y {
                    // descending y
                    pb.y.cmp(&pa.y)
                } else {
                    // ascending x
                    pa.x.cmp(&pb.x)
                }
            });
            self.minima_list_sorted = true;
        }
        for lm in self.minima_list.iter().rev() {
            self.scanline_list.push(self.vertex_list[lm.vertex].pt.y);
        }
        self.current_locmin = 0;
        self.actives = NONE;
        self.sel = NONE;
        self.succeeded = true;
    }

    #[inline]
    fn insert_scanline(&mut self, y: i64) {
        self.scanline_list.push(y);
    }

    fn pop_scanline(&mut self) -> Option<i64> {
        let y = self.scanline_list.pop()?;
        while let Some(&t) = self.scanline_list.peek() {
            if t == y {
                self.scanline_list.pop();
            } else {
                break;
            }
        }
        Some(y)
    }

    fn pop_local_minima(&mut self, y: i64) -> Option<usize> {
        if self.current_locmin >= self.minima_list.len() {
            return None;
        }
        let lm = self.minima_list[self.current_locmin];
        if self.vertex_list[lm.vertex].pt.y != y {
            return None;
        }
        let res = self.current_locmin;
        self.current_locmin += 1;
        Some(res)
    }
}

pub fn get_dx(pt1: Point64, pt2: Point64) -> f64 {
    let dy = (pt2.y - pt1.y) as f64;
    if dy != 0.0 {
        (pt2.x - pt1.x) as f64 / dy
    } else if pt2.x > pt1.x {
        -f64::MAX
    } else {
        f64::MAX
    }
}

pub fn top_x(ae_bot: Point64, ae_top: Point64, dx: f64, current_y: i64) -> i64 {
    if current_y == ae_top.y || ae_top.x == ae_bot.x {
        ae_top.x
    } else if current_y == ae_bot.y {
        ae_bot.x
    } else {
        ae_bot.x + nearbyint(dx * (current_y - ae_bot.y) as f64) as i64
    }
}

