// ---------------------------------------------------------------------------
// output records / output points
// ---------------------------------------------------------------------------

impl Clipper {
    fn new_out_rec(&mut self) -> usize {
        let idx = self.outrec_list.len();
        self.outrec_list.push(OutRec {
            idx,
            owner: NONE,
            front_edge: NONE,
            back_edge: NONE,
            pts: NONE,
            is_open: false,
            splits: Vec::new(),
        });
        idx
    }

    fn new_out_pt(&mut self, pt: Point64, outrec: usize) -> usize {
        let idx = self.outpt_list.len();
        self.outpt_list.push(OutPt {
            pt,
            next: idx,
            prev: idx,
            outrec,
            horz: NONE,
        });
        idx
    }

    fn get_real_out_rec(&self, mut outrec: usize) -> usize {
        while outrec != NONE && self.outrec_list[outrec].pts == NONE {
            outrec = self.outrec_list[outrec].owner;
        }
        outrec
    }

    fn set_sides(&mut self, outrec: usize, start_edge: usize, end_edge: usize) {
        self.outrec_list[outrec].front_edge = start_edge;
        self.outrec_list[outrec].back_edge = end_edge;
    }

    fn swap_outrecs(&mut self, e1: usize, e2: usize) {
        let or1 = self.e(e1).outrec;
        let or2 = self.e(e2).outrec;
        if or1 == or2 {
            let front = self.outrec_list[or1].front_edge;
            self.outrec_list[or1].front_edge = self.outrec_list[or1].back_edge;
            self.outrec_list[or1].back_edge = front;
            return;
        }
        if or1 != NONE {
            if self.outrec_list[or1].front_edge == e1 {
                self.outrec_list[or1].front_edge = e2;
            } else {
                self.outrec_list[or1].back_edge = e2;
            }
        }
        if or2 != NONE {
            if self.outrec_list[or2].front_edge == e2 {
                self.outrec_list[or2].front_edge = e1;
            } else {
                self.outrec_list[or2].back_edge = e1;
            }
        }
        self.active_list[e1].outrec = or2;
        self.active_list[e2].outrec = or1;
    }

    fn swap_front_back_sides(&mut self, outrec: usize) {
        let tmp = self.outrec_list[outrec].front_edge;
        self.outrec_list[outrec].front_edge = self.outrec_list[outrec].back_edge;
        self.outrec_list[outrec].back_edge = tmp;
        let pts = self.outrec_list[outrec].pts;
        self.outrec_list[outrec].pts = self.op(pts).next;
    }

    fn outrec_is_ascending(&self, hot_edge: usize) -> bool {
        self.outrec_list[self.e(hot_edge).outrec].front_edge == hot_edge
    }

    fn uncouple_outrec(&mut self, ae: usize) {
        let outrec = self.e(ae).outrec;
        if outrec == NONE {
            return;
        }
        let f = self.outrec_list[outrec].front_edge;
        let b = self.outrec_list[outrec].back_edge;
        if f != NONE {
            self.active_list[f].outrec = NONE;
        }
        if b != NONE {
            self.active_list[b].outrec = NONE;
        }
        self.outrec_list[outrec].front_edge = NONE;
        self.outrec_list[outrec].back_edge = NONE;
    }

    fn add_out_pt(&mut self, e: usize, pt: Point64) -> usize {
        let outrec = self.e(e).outrec;
        let to_front = self.is_front(e);
        let op_front = self.outrec_list[outrec].pts;
        let op_back = self.op(op_front).next;

        if to_front {
            if pt == self.op(op_front).pt {
                return op_front;
            }
        } else if pt == self.op(op_back).pt {
            return op_back;
        }

        let op = self.new_out_pt(pt, outrec);
        self.outpt_list[op_back].prev = op;
        self.outpt_list[op].prev = op_front;
        self.outpt_list[op].next = op_back;
        self.outpt_list[op_front].next = op;
        if to_front {
            self.outrec_list[outrec].pts = op;
        }
        op
    }

    fn add_local_min_poly(&mut self, e1: usize, e2: usize, pt: Point64, is_new: bool) -> usize {
        let outrec = self.new_out_rec();
        self.active_list[e1].outrec = outrec;
        self.active_list[e2].outrec = outrec;

        if self.is_open(e1) {
            self.outrec_list[outrec].owner = NONE;
            self.outrec_list[outrec].is_open = true;
            if self.e(e1).wind_dx > 0 {
                self.set_sides(outrec, e1, e2);
            } else {
                self.set_sides(outrec, e2, e1);
            }
        } else {
            let prev_hot_edge = self.get_prev_hot_edge(e1);
            if prev_hot_edge != NONE {
                self.outrec_list[outrec].owner = self.e(prev_hot_edge).outrec;
