        let or1 = self.e(e1).outrec;
        let or2 = self.e(e2).outrec;
        let p1_st = self.outrec_list[or1].pts;
        let p2_st = self.outrec_list[or2].pts;
        let p1_end = self.op(p1_st).next;
        let p2_end = self.op(p2_st).next;

        if self.is_front(e1) {
            self.outpt_list[p2_end].prev = p1_st;
            self.outpt_list[p1_st].next = p2_end;
            self.outpt_list[p2_st].next = p1_end;
            self.outpt_list[p1_end].prev = p2_st;
            self.outrec_list[or1].pts = p2_st;
            let fe = self.outrec_list[or2].front_edge;
            self.outrec_list[or1].front_edge = fe;
            if fe != NONE {
                self.active_list[fe].outrec = or1;
            }
        } else {
            self.outpt_list[p1_end].prev = p2_st;
            self.outpt_list[p2_st].next = p1_end;
            self.outpt_list[p1_st].next = p2_end;
            self.outpt_list[p2_end].prev = p1_st;
            let be = self.outrec_list[or2].back_edge;
            self.outrec_list[or1].back_edge = be;
            if be != NONE {
                self.active_list[be].outrec = or1;
            }
        }

        // an owner must have a lower idx otherwise it can't be a valid owner
        let owner2 = self.outrec_list[or2].owner;
        if owner2 != NONE && self.outrec_list[owner2].idx < self.outrec_list[or1].idx {
            let owner1 = self.outrec_list[or1].owner;
            if owner1 == NONE || self.outrec_list[owner2].idx < self.outrec_list[owner1].idx {
                self.outrec_list[or1].owner = owner2;
            }
        }

        self.outrec_list[or2].front_edge = NONE;
        self.outrec_list[or2].back_edge = NONE;
        self.outrec_list[or2].pts = NONE;
        self.outrec_list[or2].owner = or1;

        if self.is_open_end(e1) {
            self.outrec_list[or2].pts = self.outrec_list[or1].pts;
            self.outrec_list[or1].pts = NONE;
        }

        self.active_list[e1].outrec = NONE;
        self.active_list[e2].outrec = NONE;
    }

    fn split(&mut self, e: usize, pt: Point64) {
        if self.e(e).join_with == JoinWith::Right {
            self.active_list[e].join_with = JoinWith::NoJoin;
            let n = self.e(e).next_in_ael;
            self.active_list[n].join_with = JoinWith::NoJoin;
            self.add_local_min_poly(e, n, pt, true);
        } else {
            self.active_list[e].join_with = JoinWith::NoJoin;
            let p = self.e(e).prev_in_ael;
            self.active_list[p].join_with = JoinWith::NoJoin;
            self.add_local_min_poly(p, e, pt, true);
        }
    }

    fn dispose_out_pt(&mut self, op: usize) -> usize {
        let result = self.op(op).next;
        let prev = self.op(op).prev;
        let next = self.op(op).next;
        self.outpt_list[prev].next = next;
        self.outpt_list[next].prev = prev;
        result
    }

    fn duplicate_op(&mut self, op: usize, insert_after: bool) -> usize {
        let pt = self.op(op).pt;
        let outrec = self.op(op).outrec;
        let result = self.new_out_pt(pt, outrec);
        if insert_after {
            let next = self.op(op).next;
            self.outpt_list[result].next = next;
            self.outpt_list[next].prev = result;
            self.outpt_list[result].prev = op;
            self.outpt_list[op].next = result;
        } else {
            let prev = self.op(op).prev;
            self.outpt_list[result].prev = prev;
            self.outpt_list[prev].next = result;
            self.outpt_list[result].next = op;
            self.outpt_list[op].prev = result;
        }
        result
    }

    fn fix_out_rec_pts(&mut self, outrec: usize) {
        let start = self.outrec_list[outrec].pts;
        let mut op = start;
        loop {
            self.outpt_list[op].outrec = outrec;
            op = self.op(op).next;
            if op == start {
                break;
            }
        }
    }

    fn is_valid_closed_path(&self, op: usize) -> bool {
        op != NONE && self.op(op).next != op && self.op(op).next != self.op(op).prev
    }

    fn area_op(&self, op: usize) -> f64 {
        let mut area = 0.0f64;
        let mut op2 = op;
        loop {
            let prev = self.op(op2).prev;
            area += (self.op(prev).pt.y + self.op(op2).pt.y) as f64
                * (self.op(prev).pt.x - self.op(op2).pt.x) as f64;
            op2 = self.op(op2).next;
            if op2 == op {
                break;
            }
        }
        area * 0.5
    }
}

