// ---------------------------------------------------------------------------
// active edge list, winding counts and edge intersections
// ---------------------------------------------------------------------------

impl Clipper {
    fn is_valid_ael_order(&self, resident: usize, newcomer: usize) -> bool {
        let r = self.e(resident);
        let n = self.e(newcomer);
        if n.curr_x != r.curr_x {
            return n.curr_x > r.curr_x;
        }

        // get the turning direction  a1.top, a2.bot, a2.top
        let d = cross_product(r.top, n.bot, n.top);
        if d != 0.0 {
            return d < 0.0;
        }

        // edges must be collinear to get here
        // for starting open paths, place them according to the direction
        // they're about to turn
        if !self.is_maxima(resident) && r.top.y > n.top.y {
            return cross_product(n.bot, r.top, self.v(self.next_vertex(resident)).pt) <= 0.0;
        }
        if !self.is_maxima(newcomer) && n.top.y > r.top.y {
            return cross_product(n.bot, n.top, self.v(self.next_vertex(newcomer)).pt) >= 0.0;
        }

        let y = n.bot.y;
        let newcomer_is_left = n.is_left_bound;
        if r.bot.y != y || self.v(self.lm(r.local_min).vertex).pt.y != y {
            return n.is_left_bound;
        }
        // resident must also have just been inserted
        if r.is_left_bound != newcomer_is_left {
            return newcomer_is_left;
        }
        if cross_product(self.v(self.prev_prev_vertex(resident)).pt, r.bot, r.top) == 0.0 {
            return true;
        }
        // compare turning direction of the alternate bound
        (cross_product(
            self.v(self.prev_prev_vertex(resident)).pt,
            n.bot,
            self.v(self.prev_prev_vertex(newcomer)).pt,
        ) > 0.0)
            == newcomer_is_left
    }

    fn insert_left_edge(&mut self, e: usize) {
        if self.actives == NONE {
            self.active_list[e].prev_in_ael = NONE;
            self.active_list[e].next_in_ael = NONE;
            self.actives = e;
        } else if !self.is_valid_ael_order(self.actives, e) {
            let a = self.actives;
            self.active_list[e].prev_in_ael = NONE;
            self.active_list[e].next_in_ael = a;
            self.active_list[a].prev_in_ael = e;
            self.actives = e;
        } else {
            let mut e2 = self.actives;
            while self.e(e2).next_in_ael != NONE
                && self.is_valid_ael_order(self.e(e2).next_in_ael, e)
            {
                e2 = self.e(e2).next_in_ael;
            }
            if self.e(e2).join_with == JoinWith::Right {
                e2 = self.e(e2).next_in_ael;
            }
            let next = self.e(e2).next_in_ael;
            self.active_list[e].next_in_ael = next;
            if next != NONE {
                self.active_list[next].prev_in_ael = e;
            }
            self.active_list[e].prev_in_ael = e2;
            self.active_list[e2].next_in_ael = e;
        }
    }

    fn insert_right_edge(&mut self, e: usize, e2: usize) {
        let next = self.e(e).next_in_ael;
        self.active_list[e2].next_in_ael = next;
        if next != NONE {
            self.active_list[next].prev_in_ael = e2;
        }
        self.active_list[e2].prev_in_ael = e;
        self.active_list[e].next_in_ael = e2;
    }

    fn delete_from_ael(&mut self, e: usize) {
        let prev = self.e(e).prev_in_ael;
        let next = self.e(e).next_in_ael;
        if prev == NONE && next == NONE && self.actives != e {
            return; // not in the list
        }
        if prev != NONE {
            self.active_list[prev].next_in_ael = next;
        } else {
            self.actives = next;
        }
        if next != NONE {
            self.active_list[next].prev_in_ael = prev;
        }
        self.active_list[e].prev_in_ael = NONE;
        self.active_list[e].next_in_ael = NONE;
    }

    fn swap_positions_in_ael(&mut self, e1: usize, e2: usize) {
        // check that one or other edge hasn't already been removed from AEL
        if self.e(e1).next_in_ael == self.e(e1).prev_in_ael
            || self.e(e2).next_in_ael == self.e(e2).prev_in_ael
        {
            return;
        }

        let (prev, next);
        if self.e(e1).next_in_ael == e2 {
            next = self.e(e2).next_in_ael;
            if next != NONE {
                self.active_list[next].prev_in_ael = e1;
            }
            prev = self.e(e1).prev_in_ael;
            if prev != NONE {
                self.active_list[prev].next_in_ael = e2;
            }
            self.active_list[e2].prev_in_ael = prev;
            self.active_list[e2].next_in_ael = e1;
            self.active_list[e1].prev_in_ael = e2;
            self.active_list[e1].next_in_ael = next;
            if prev == NONE {
                self.actives = e2;
            }
        } else if self.e(e2).next_in_ael == e1 {
            next = self.e(e1).next_in_ael;
            if next != NONE {
                self.active_list[next].prev_in_ael = e2;
            }
            prev = self.e(e2).prev_in_ael;
            if prev != NONE {
                self.active_list[prev].next_in_ael = e1;
            }
            self.active_list[e1].prev_in_ael = prev;
            self.active_list[e1].next_in_ael = e2;
            self.active_list[e2].prev_in_ael = e1;
            self.active_list[e2].next_in_ael = next;
            if prev == NONE {
                self.actives = e1;
            }
        } else {
            // nb: swapping non-adjacent edges is not supported by the C++ code
            return;
        }
    }

    fn set_wind_count_for_closed_path_edge(&mut self, ae: usize) {
        // Wind counts refer to polygon regions not edges, so here an edge's
        // WindCnt indicates the higher of the wind counts of the regions
        // touching the edge.
        let pt = self.poly_type(ae);
        let mut ae2 = self.e(ae).prev_in_ael;
        while ae2 != NONE && (self.poly_type(ae2) != pt || self.is_open(ae2)) {
            ae2 = self.e(ae2).prev_in_ael;
        }

        if ae2 == NONE {
            self.active_list[ae].wind_cnt = self.e(ae).wind_dx;
            ae2 = self.actives;
        } else if self.fillrule == FillRule::EvenOdd {
            self.active_list[ae].wind_cnt = self.e(ae).wind_dx;
            self.active_list[ae].wind_cnt2 = self.e(ae2).wind_cnt2;
            ae2 = self.e(ae2).next_in_ael;
        } else {
            // NonZero, positive, or negative filling here ...
            // if e's WindCnt is in the SAME direction as its WindDx, then polygon
            // filling will be on the right of 'e'.
            let a2 = self.e(ae2);
            let a = self.e(ae);
            if a2.wind_cnt * a2.wind_dx < 0 {
                // opposite directions so 'ae' is outside 'ae2'
                if a2.wind_cnt.abs() > 1 {
                    // outside prev poly but still inside another
                    if a2.wind_dx * a.wind_dx < 0 {
                        // reversing direction so use the same WC
                        self.active_list[ae].wind_cnt = a2.wind_cnt;
                    } else {
                        // otherwise keep 'reducing' the WC by 1 (ie towards 0)
                        self.active_list[ae].wind_cnt = a2.wind_cnt + a.wind_dx;
                    }
                } else {
                    // now outside all polys of same polytype so set own WC
                    self.active_list[ae].wind_cnt = if self.is_open(ae) { 1 } else { a.wind_dx };
                }
            } else {
                // 'ae' must be inside 'ae2'
                if a2.wind_dx * a.wind_dx < 0 {
                    // reversing direction so use the same WC
                    self.active_list[ae].wind_cnt = a2.wind_cnt;
                } else {
                    // otherwise keep 'increasing' the WC by 1 (ie away from 0)
                    self.active_list[ae].wind_cnt = a2.wind_cnt + a.wind_dx;
                }
            }
            self.active_list[ae].wind_cnt2 = self.e(ae2).wind_cnt2;
            ae2 = self.e(ae2).next_in_ael;
        }

        // update wind_cnt2 ...
        if self.fillrule == FillRule::EvenOdd {
            while ae2 != ae {
                if self.poly_type(ae2) != pt && !self.is_open(ae2) {
                    self.active_list[ae].wind_cnt2 =
                        if self.e(ae).wind_cnt2 == 0 { 1 } else { 0 };
                }
                ae2 = self.e(ae2).next_in_ael;
            }
        } else {
            while ae2 != ae {
                if self.poly_type(ae2) != pt && !self.is_open(ae2) {
                    self.active_list[ae].wind_cnt2 += self.e(ae2).wind_dx;
                }
                ae2 = self.e(ae2).next_in_ael;
            }
        }
    }

    fn is_contributing_closed(&self, ae: usize) -> bool {
        let a = self.e(ae);
        match self.fillrule {
            FillRule::EvenOdd => {}
            FillRule::NonZero => {
                if a.wind_cnt.abs() != 1 {
                    return false;
                }
            }
            FillRule::Positive => {
                if a.wind_cnt != 1 {
                    return false;
                }
            }
            FillRule::Negative => {
                if a.wind_cnt != -1 {
                    return false;
                }
            }
        }

        match self.cliptype {
            ClipType::Intersection => match self.fillrule {
                FillRule::Positive => a.wind_cnt2 > 0,
                FillRule::Negative => a.wind_cnt2 < 0,
                _ => a.wind_cnt2 != 0,
            },
            ClipType::Union => match self.fillrule {
                FillRule::Positive => a.wind_cnt2 <= 0,
                FillRule::Negative => a.wind_cnt2 >= 0,
                _ => a.wind_cnt2 == 0,
            },
            ClipType::Difference => {
                let result = match self.fillrule {
                    FillRule::Positive => a.wind_cnt2 <= 0,
                    FillRule::Negative => a.wind_cnt2 >= 0,
                    _ => a.wind_cnt2 == 0,
                };
                if self.poly_type(ae) == PathType::Subject {
                    result
                } else {
                    !result
                }
            }
            ClipType::Xor => true,
            ClipType::NoClip => false,
        }
    }

    fn intersect_edges(&mut self, ae1: usize, ae2: usize, pt: Point64) -> usize {
        let mut result_op = NONE;

        // UPDATE WINDING COUNTS ...
        if self.poly_type(ae1) == self.poly_type(ae2) {
            if self.fillrule == FillRule::EvenOdd {
                let old = self.e(ae1).wind_cnt;
                self.active_list[ae1].wind_cnt = self.e(ae2).wind_cnt;
                self.active_list[ae2].wind_cnt = old;
            } else {
                if self.e(ae1).wind_cnt + self.e(ae2).wind_dx == 0 {
                    self.active_list[ae1].wind_cnt = -self.e(ae1).wind_cnt;
                } else {
                    self.active_list[ae1].wind_cnt += self.e(ae2).wind_dx;
                }
                if self.e(ae2).wind_cnt - self.e(ae1).wind_dx == 0 {
                    self.active_list[ae2].wind_cnt = -self.e(ae2).wind_cnt;
                } else {
                    self.active_list[ae2].wind_cnt -= self.e(ae1).wind_dx;
                }
            }
        } else if self.fillrule != FillRule::EvenOdd {
            self.active_list[ae1].wind_cnt2 += self.e(ae2).wind_dx;
            self.active_list[ae2].wind_cnt2 -= self.e(ae1).wind_dx;
        } else {
            self.active_list[ae1].wind_cnt2 = if self.e(ae1).wind_cnt2 == 0 { 1 } else { 0 };
            self.active_list[ae2].wind_cnt2 = if self.e(ae2).wind_cnt2 == 0 { 1 } else { 0 };
        }

        let (old_e1_windcnt, old_e2_windcnt) = match self.fillrule {
            FillRule::Positive => (self.e(ae1).wind_cnt, self.e(ae2).wind_cnt),
            FillRule::Negative => (-self.e(ae1).wind_cnt, -self.e(ae2).wind_cnt),
            _ => (self.e(ae1).wind_cnt.abs(), self.e(ae2).wind_cnt.abs()),
        };

        let e1_windcnt_in_01 = old_e1_windcnt == 0 || old_e1_windcnt == 1;
        let e2_windcnt_in_01 = old_e2_windcnt == 0 || old_e2_windcnt == 1;

        if (!self.is_hot_edge(ae1) && !e1_windcnt_in_01)
            || (!self.is_hot_edge(ae2) && !e2_windcnt_in_01)
        {
            return NONE;
        }

        // NOW PROCESS THE INTERSECTION ...
        if self.is_hot_edge(ae1) && self.is_hot_edge(ae2) {
            if (old_e1_windcnt != 0 && old_e1_windcnt != 1)
                || (old_e2_windcnt != 0 && old_e2_windcnt != 1)
                || (self.poly_type(ae1) != self.poly_type(ae2) && self.cliptype != ClipType::Xor)
            {
                result_op = self.add_local_max_poly(ae1, ae2, pt);
            } else if self.is_front(ae1) || self.e(ae1).outrec == self.e(ae2).outrec {
                // this 'else if' condition isn't strictly needed but it's sensible
                // to split polygons that only touch at a common vertex
                result_op = self.add_local_max_poly(ae1, ae2, pt);
                self.add_local_min_poly(ae1, ae2, pt, false);
            } else {
                // can't treat as maxima & minima
                result_op = self.add_out_pt(ae1, pt);
                self.add_out_pt(ae2, pt);
                self.swap_outrecs(ae1, ae2);
            }
        } else if self.is_hot_edge(ae1) {
            result_op = self.add_out_pt(ae1, pt);
            self.swap_outrecs(ae1, ae2);
        } else if self.is_hot_edge(ae2) {
            result_op = self.add_out_pt(ae2, pt);
            self.swap_outrecs(ae1, ae2);
        } else {
            // neither edge is 'hot'
            let (e1_wc2, e2_wc2) = match self.fillrule {
                FillRule::Positive => (self.e(ae1).wind_cnt2, self.e(ae2).wind_cnt2),
                FillRule::Negative => (-self.e(ae1).wind_cnt2, -self.e(ae2).wind_cnt2),
                _ => (self.e(ae1).wind_cnt2.abs(), self.e(ae2).wind_cnt2.abs()),
            };

            if !self.is_same_poly_type(ae1, ae2) {
                result_op = self.add_local_min_poly(ae1, ae2, pt, false);
            } else if old_e1_windcnt == 1 && old_e2_windcnt == 1 {
                result_op = NONE;
                match self.cliptype {
                    ClipType::Union => {
                        if e1_wc2 <= 0 && e2_wc2 <= 0 {
                            result_op = self.add_local_min_poly(ae1, ae2, pt, false);
                        }
                    }
                    ClipType::Difference => {
                        if (self.poly_type(ae1) == PathType::Clip && e1_wc2 > 0 && e2_wc2 > 0)
                            || (self.poly_type(ae1) == PathType::Subject
                                && e1_wc2 <= 0
                                && e2_wc2 <= 0)
                        {
                            result_op = self.add_local_min_poly(ae1, ae2, pt, false);
                        }
                    }
                    ClipType::Xor => {
                        result_op = self.add_local_min_poly(ae1, ae2, pt, false);
                    }
                    _ => {
                        // ClipType::Intersection
                        if e1_wc2 > 0 && e2_wc2 > 0 {
                            result_op = self.add_local_min_poly(ae1, ae2, pt, false);
                        }
                    }
                }
            }
        }
        result_op
    }
}

