// ---------------------------------------------------------------------------
// the sweep
// ---------------------------------------------------------------------------

impl Clipper {
    fn insert_local_minima_into_ael(&mut self, bot_y: i64) {
        while let Some(local_minima) = self.pop_local_minima(bot_y) {
            let lmv = self.lm(local_minima).vertex;
            let mut left_bound;
            let mut right_bound;

            if self.v(lmv).flags & VF_OPEN_START != 0 {
                left_bound = NONE;
            } else {
                let mut a = Active::new();
                a.bot = self.v(lmv).pt;
                a.curr_x = a.bot.x;
                a.wind_dx = -1;
                a.vertex_top = self.v(lmv).prev; // ie descending
                a.top = self.v(a.vertex_top).pt;
                a.outrec = NONE;
                a.local_min = local_minima;
                a.dx = get_dx(a.bot, a.top);
                self.active_list.push(a);
                left_bound = self.active_list.len() - 1;
            }

            if self.v(lmv).flags & VF_OPEN_END != 0 {
                right_bound = NONE;
            } else {
                let mut a = Active::new();
                a.bot = self.v(lmv).pt;
                a.curr_x = a.bot.x;
                a.wind_dx = 1;
                a.vertex_top = self.v(lmv).next; // ie ascending
                a.top = self.v(a.vertex_top).pt;
                a.outrec = NONE;
                a.local_min = local_minima;
                a.dx = get_dx(a.bot, a.top);
                self.active_list.push(a);
                right_bound = self.active_list.len() - 1;
            }

            // Currently LeftB is just the descending bound and RightB is the
            // ascending. Now if the LeftB isn't on the left of RightB then we
            // need to swap them.
            if left_bound != NONE && right_bound != NONE {
                if self.is_horizontal(left_bound) {
                    if self.is_heading_right_horz(left_bound) {
                        std::mem::swap(&mut left_bound, &mut right_bound);
                    }
                } else if self.is_horizontal(right_bound) {
                    if self.is_heading_left_horz(right_bound) {
                        std::mem::swap(&mut left_bound, &mut right_bound);
                    }
                } else if self.e(left_bound).dx < self.e(right_bound).dx {
                    std::mem::swap(&mut left_bound, &mut right_bound);
                }
            } else if left_bound == NONE {
                left_bound = right_bound;
                right_bound = NONE;
            }

            let contributing;
            self.active_list[left_bound].is_left_bound = true;
            self.insert_left_edge(left_bound);

            if self.is_open(left_bound) {
                self.set_wind_count_for_open_path_edge(left_bound);
                contributing = self.is_contributing_open(left_bound);
            } else {
                self.set_wind_count_for_closed_path_edge(left_bound);
                contributing = self.is_contributing_closed(left_bound);
            }

            if right_bound != NONE {
                self.active_list[right_bound].is_left_bound = false;
                self.active_list[right_bound].wind_cnt = self.e(left_bound).wind_cnt;
                self.active_list[right_bound].wind_cnt2 = self.e(left_bound).wind_cnt2;
                self.insert_right_edge(left_bound, right_bound);
                if contributing {
                    let bot = self.e(left_bound).bot;
                    self.add_local_min_poly(left_bound, right_bound, bot, true);
                    if !self.is_horizontal(left_bound) {
                        self.check_join_left(left_bound, bot, false);
                    }
                }

                while self.e(right_bound).next_in_ael != NONE
                    && self.is_valid_ael_order(self.e(right_bound).next_in_ael, right_bound)
                {
                    let nxt = self.e(right_bound).next_in_ael;
                    let bot = self.e(right_bound).bot;
                    self.intersect_edges(right_bound, nxt, bot);
                    self.swap_positions_in_ael(right_bound, nxt);
                }

                if self.is_horizontal(right_bound) {
                    self.push_horz(right_bound);
                } else {
                    let bot = self.e(right_bound).bot;
                    self.check_join_right(right_bound, bot, false);
                    let ty = self.e(right_bound).top.y;
                    self.insert_scanline(ty);
                }
            } else if contributing {
                let bot = self.e(left_bound).bot;
                self.start_open_path(left_bound, bot);
            }

            if self.is_horizontal(left_bound) {
                self.push_horz(left_bound);
            } else {
                let ty = self.e(left_bound).top.y;
                self.insert_scanline(ty);
            }
        }
    }

    fn push_horz(&mut self, e: usize) {
        self.active_list[e].next_in_sel = self.sel;
        self.sel = e;
    }

    fn pop_horz(&mut self) -> usize {
        let e = self.sel;
        if e == NONE {
            return NONE;
        }
        self.sel = self.e(e).next_in_sel;
        e
    }

    // open paths are never used by this program but the hooks are kept so the
    // control flow matches the reference implementation
    fn set_wind_count_for_open_path_edge(&mut self, _e: usize) {}
    fn is_contributing_open(&self, _e: usize) -> bool {
        false
    }
    fn start_open_path(&mut self, _e: usize, _pt: Point64) -> usize {
        NONE
    }

    fn check_join_left(&mut self, e: usize, pt: Point64, check_curr_x: bool) {
        let prev = self.e(e).prev_in_ael;
        if prev == NONE
            || !self.is_hot_edge(e)
            || !self.is_hot_edge(prev)
            || self.is_horizontal(e)
            || self.is_horizontal(prev)
            || self.is_open(e)
            || self.is_open(prev)
        {
            return;
        }
        if (pt.y < self.e(e).top.y + 2 || pt.y < self.e(prev).top.y + 2)
            && (self.e(e).bot.y > pt.y || self.e(prev).bot.y > pt.y)
        {
            return;
        }

        if check_curr_x {
            if perpendic_dist_from_line_sqrd(pt, self.e(prev).bot, self.e(prev).top) > 0.25 {
                return;
            }
        } else if self.e(e).curr_x != self.e(prev).curr_x {
            return;
        }
        if !is_collinear(self.e(e).top, pt, self.e(prev).top) {
            return;
        }

        let or_e = self.outrec_list[self.e(e).outrec].idx;
        let or_p = self.outrec_list[self.e(prev).outrec].idx;
        if or_e == or_p {
            self.add_local_max_poly(prev, e, pt);
        } else if or_e < or_p {
            self.join_outrec_paths(e, prev);
        } else {
            self.join_outrec_paths(prev, e);
        }
        self.active_list[prev].join_with = JoinWith::Right;
        self.active_list[e].join_with = JoinWith::Left;
    }

    fn check_join_right(&mut self, e: usize, pt: Point64, check_curr_x: bool) {
        let next = self.e(e).next_in_ael;
        if next == NONE
            || !self.is_hot_edge(e)
            || !self.is_hot_edge(next)
            || self.is_horizontal(e)
            || self.is_horizontal(next)
            || self.is_open(e)
            || self.is_open(next)
        {
            return;
        }
        if (pt.y < self.e(e).top.y + 2 || pt.y < self.e(next).top.y + 2)
            && (self.e(e).bot.y > pt.y || self.e(next).bot.y > pt.y)
        {
            return;
        }

        if check_curr_x {
            if perpendic_dist_from_line_sqrd(pt, self.e(next).bot, self.e(next).top) > 0.35 {
                return;
            }
        } else if self.e(e).curr_x != self.e(next).curr_x {
            return;
        }
        if !is_collinear(self.e(e).top, pt, self.e(next).top) {
            return;
        }

        let or_e = self.outrec_list[self.e(e).outrec].idx;
        let or_n = self.outrec_list[self.e(next).outrec].idx;
        if or_e == or_n {
            self.add_local_max_poly(e, next, pt);
        } else if or_e < or_n {
            self.join_outrec_paths(e, next);
        } else {
            self.join_outrec_paths(next, e);
        }
        self.active_list[e].join_with = JoinWith::Right;
        self.active_list[next].join_with = JoinWith::Left;
    }

    fn get_last_op(&self, hot_edge: usize) -> usize {
        let outrec = self.e(hot_edge).outrec;
        let result = self.outrec_list[outrec].pts;
        if self.outrec_list[outrec].front_edge == hot_edge {
            result
        } else {
            self.op(result).next
        }
    }

    fn add_trial_horz_join(&mut self, op: usize) {
        if !self.outrec_list[self.op(op).outrec].is_open {
            self.horz_seg_list.push(HorzSegment {
                left_op: op,
                right_op: NONE,
                left_to_right: true,
            });
        }
    }

    fn trim_horz(&mut self, horz: usize, preserve_collinear: bool) {
        let mut was_trimmed = false;
        let mut pt = self.v(self.next_vertex(horz)).pt;
        while pt.y == self.e(horz).top.y {
            // always trim 180 deg. spikes (in closed paths)
            // but otherwise break if preserveCollinear = true
            if preserve_collinear
                && (pt.x < self.e(horz).top.x) != (self.e(horz).bot.x < self.e(horz).top.x)
            {
                break;
            }
            self.active_list[horz].vertex_top = self.next_vertex(horz);
            self.active_list[horz].top = pt;
            was_trimmed = true;
            if self.is_maxima(horz) {
                break;
            }
            pt = self.v(self.next_vertex(horz)).pt;
        }
        if was_trimmed {
            self.set_dx(horz);
        }
    }

    fn update_edge_into_ael(&mut self, e: usize) {
        self.active_list[e].bot = self.e(e).top;
        self.active_list[e].vertex_top = self.next_vertex(e);
        self.active_list[e].top = self.v(self.e(e).vertex_top).pt;
        self.active_list[e].curr_x = self.e(e).bot.x;
        self.set_dx(e);

        if self.is_joined(e) {
            let bot = self.e(e).bot;
            self.split(e, bot);
        }

        if self.is_horizontal(e) {
            if !self.is_open(e) {
                let pc = self.preserve_collinear;
                self.trim_horz(e, pc);
            }
            return;
        }
        let ty = self.e(e).top.y;
        self.insert_scanline(ty);
        let bot = self.e(e).bot;
        self.check_join_left(e, bot, false);
        self.check_join_right(e, bot, true);
    }

    fn reset_horz_direction(&self, horz: usize, vertex_max: usize) -> (bool, i64, i64) {
        let h = self.e(horz);
        if h.bot.x == h.top.x {
            // the horizontal edge is going nowhere ...
            let left_x = h.curr_x;
            let right_x = h.curr_x;
            let mut e = h.next_in_ael;
            while e != NONE && self.e(e).vertex_top != vertex_max {
                e = self.e(e).next_in_ael;
            }
            (e != NONE, left_x, right_x)
        } else if h.curr_x < h.top.x {
            (true, h.curr_x, h.top.x)
        } else {
            (false, h.top.x, h.curr_x)
        }
    }

    fn do_horizontal(&mut self, horz: usize) {
        let horz_is_open = self.is_open(horz);
        let y = self.e(horz).bot.y;
        let vertex_max = if horz_is_open {
            self.get_curr_y_maxima_vertex_open(horz)
        } else {
            self.get_curr_y_maxima_vertex(horz)
        };

        let (mut is_left_to_right, mut left_x, mut right_x) =
            self.reset_horz_direction(horz, vertex_max);

        if self.is_hot_edge(horz) {
            let cx = self.e(horz).curr_x;
            let op = self.add_out_pt(horz, Point64::new(cx, y));
            self.add_trial_horz_join(op);
        }

        loop {
            // loop through consecutive horizontal edges
            let mut e = if is_left_to_right {
                self.e(horz).next_in_ael
            } else {
                self.e(horz).prev_in_ael
            };

            while e != NONE {
                if self.e(e).vertex_top == vertex_max {
                    if self.is_hot_edge(horz) && self.is_joined(e) {
                        let top = self.e(e).top;
                        self.split(e, top);
                    }
                    if self.is_hot_edge(horz) {
                        while self.e(horz).vertex_top != vertex_max {
                            let top = self.e(horz).top;
                            self.add_out_pt(horz, top);
                            self.update_edge_into_ael(horz);
                        }
                        let top = self.e(horz).top;
                        if is_left_to_right {
                            self.add_local_max_poly(horz, e, top);
                        } else {
                            self.add_local_max_poly(e, horz, top);
                        }
                    }
                    self.delete_from_ael(e);
                    self.delete_from_ael(horz);
                    return;
                }

                // if horzEdge is a maxima, keep going until we reach its maxima
                // pair, otherwise check for break conditions
                if vertex_max != self.e(horz).vertex_top || self.is_open_end(horz) {
                    // stop when 'e' is beyond the end of the horizontal line
                    if is_left_to_right && self.e(e).curr_x > right_x {
                        break;
                    }
                    if !is_left_to_right && self.e(e).curr_x < left_x {
                        break;
                    }

                    if self.e(e).curr_x == self.e(horz).top.x && !self.is_horizontal(e) {
                        let pt = self.v(self.next_vertex(horz)).pt;
                        let ea = self.e(e);
                        if is_left_to_right {
                            if self.is_open(e)
                                && !self.is_same_poly_type(e, horz)
                                && !self.is_hot_edge(e)
                            {
                                if top_x(ea.bot, ea.top, ea.dx, pt.y) > pt.x {
                                    break;
                                }
                            } else if top_x(ea.bot, ea.top, ea.dx, pt.y) >= pt.x {
                                break;
                            }
                        } else if self.is_open(e)
                            && !self.is_same_poly_type(e, horz)
                            && !self.is_hot_edge(e)
                        {
                            if top_x(ea.bot, ea.top, ea.dx, pt.y) < pt.x {
                                break;
                            }
                        } else if top_x(ea.bot, ea.top, ea.dx, pt.y) <= pt.x {
                            break;
                        }
                    }
                }

                let pt = Point64::new(self.e(e).curr_x, self.e(horz).bot.y);

                if is_left_to_right {
                    self.intersect_edges(horz, e, pt);
                    self.swap_positions_in_ael(horz, e);
                    self.check_join_left(e, pt, false);
                    self.active_list[horz].curr_x = self.e(e).curr_x;
                    e = self.e(horz).next_in_ael;
                } else {
                    self.intersect_edges(e, horz, pt);
                    self.swap_positions_in_ael(e, horz);
                    self.check_join_right(e, pt, false);
                    self.active_list[horz].curr_x = self.e(e).curr_x;
                    e = self.e(horz).prev_in_ael;
                }

                if self.is_hot_edge(horz) {
                    let op = self.get_last_op(horz);
                    self.add_trial_horz_join(op);
                }
            }

            // we've reached the end of this horizontal
            if horz_is_open && self.is_open_end(horz) {
                if self.is_hot_edge(horz) {
                    let top = self.e(horz).top;
                    self.add_out_pt(horz, top);
                    let o = self.e(horz).outrec;
                    if self.is_front(horz) {
                        self.outrec_list[o].front_edge = NONE;
                    } else {
                        self.outrec_list[o].back_edge = NONE;
                    }
                    self.active_list[horz].outrec = NONE;
                }
                self.delete_from_ael(horz);
                return;
            }

            if self.v(self.next_vertex(horz)).pt.y != self.e(horz).top.y {
                break;
            }

            // still more horizontals in bound to process ...
            if self.is_hot_edge(horz) {
                let top = self.e(horz).top;
                self.add_out_pt(horz, top);
            }
            self.update_edge_into_ael(horz);

            let r = self.reset_horz_direction(horz, vertex_max);
            is_left_to_right = r.0;
            left_x = r.1;
            right_x = r.2;
            let _ = (left_x, right_x);
        }

        if self.is_hot_edge(horz) {
            let top = self.e(horz).top;
            let op = self.add_out_pt(horz, top);
            self.add_trial_horz_join(op);
        }
        self.update_edge_into_ael(horz);
    }

    fn get_curr_y_maxima_vertex_open(&self, e: usize) -> usize {
        let a = self.e(e);
        let mut result = a.vertex_top;
        if a.wind_dx > 0 {
            while self.v(self.v(result).next).pt.y == self.v(result).pt.y {
                if self.v(result).flags & (VF_OPEN_END | VF_LOCAL_MAX) != 0 {
                    break;
                }
                result = self.v(result).next;
            }
        } else {
            while self.v(self.v(result).prev).pt.y == self.v(result).pt.y {
                if self.v(result).flags & (VF_OPEN_END | VF_LOCAL_MAX) != 0 {
                    break;
                }
                result = self.v(result).prev;
            }
        }
        if !self.is_maxima_v(result) {
            NONE
        } else {
            result
        }
    }

    fn do_top_of_scanbeam(&mut self, y: i64) {
        self.sel = NONE; // sel_ is reused to flag horizontals (see push_horz)
        let mut e = self.actives;
        while e != NONE {
            // nb: 'e' will never be horizontal here
            if self.e(e).top.y == y {
                self.active_list[e].curr_x = self.e(e).top.x;
                if self.is_maxima(e) {
                    e = self.do_maxima(e); // TOP OF BOUND (MAXIMA)
                    continue;
                }
                // INTERMEDIATE VERTEX ...
                if self.is_hot_edge(e) {
                    let top = self.e(e).top;
                    self.add_out_pt(e, top);
                }
                self.update_edge_into_ael(e);
                if self.is_horizontal(e) {
                    self.push_horz(e);
                }
            } else {
                let a = self.e(e);
                self.active_list[e].curr_x = top_x(a.bot, a.top, a.dx, y);
            }
            e = self.e(e).next_in_ael;
        }
    }

    fn do_maxima(&mut self, e: usize) -> usize {
        let prev_e = self.e(e).prev_in_ael;
        let mut next_e = self.e(e).next_in_ael;

        if self.is_open_end(e) {
            if self.is_hot_edge(e) {
                let top = self.e(e).top;
                self.add_out_pt(e, top);
            }
            if !self.is_horizontal(e) {
                if self.is_hot_edge(e) {
                    let o = self.e(e).outrec;
                    if self.is_front(e) {
                        self.outrec_list[o].front_edge = NONE;
                    } else {
                        self.outrec_list[o].back_edge = NONE;
                    }
                    self.active_list[e].outrec = NONE;
                }
                self.delete_from_ael(e);
            }
            return next_e;
        }

        let max_pair = self.get_maxima_pair(e);
        if max_pair == NONE {
            return next_e; // e's maxima pair is horizontal
        }

        if self.is_joined(e) {
            let top = self.e(e).top;
            self.split(e, top);
        }
        if self.is_joined(max_pair) {
            let top = self.e(max_pair).top;
            self.split(max_pair, top);
        }

        // only non-horizontal maxima here.
        // process any edges between maxima pair ...
        while next_e != max_pair {
            let top = self.e(e).top;
            self.intersect_edges(e, next_e, top);
            self.swap_positions_in_ael(e, next_e);
            next_e = self.e(e).next_in_ael;
        }

        if self.is_hot_edge(e) {
            let top = self.e(e).top;
            self.add_local_max_poly(e, max_pair, top);
        }

        self.delete_from_ael(e);
        self.delete_from_ael(max_pair);
        if prev_e != NONE {
            self.e(prev_e).next_in_ael
        } else {
            self.actives
        }
    }

    fn adjust_curr_x_and_copy_to_sel(&mut self, top_y: i64) {
        let mut e = self.actives;
        self.sel = e;
        while e != NONE {
            let a = self.e(e);
            self.active_list[e].prev_in_sel = a.prev_in_ael;
            self.active_list[e].next_in_sel = a.next_in_ael;
            self.active_list[e].jump = a.next_in_ael;
            if a.join_with == JoinWith::Left {
                self.active_list[e].curr_x = self.e(a.prev_in_ael).curr_x;
            } else {
                self.active_list[e].curr_x = top_x(a.bot, a.top, a.dx, top_y);
            }
            e = self.e(e).next_in_ael;
        }
    }

    fn extract_from_sel(&mut self, ae: usize) -> usize {
        let res = self.e(ae).next_in_sel;
        let prev = self.e(ae).prev_in_sel;
        if res != NONE {
            self.active_list[res].prev_in_sel = prev;
        }
        if prev != NONE {
            self.active_list[prev].next_in_sel = res;
        }
        res
    }

    fn insert1_before2_in_sel(&mut self, ae1: usize, ae2: usize) {
        let prev = self.e(ae2).prev_in_sel;
        self.active_list[ae1].prev_in_sel = prev;
        if prev != NONE {
            self.active_list[prev].next_in_sel = ae1;
        }
        self.active_list[ae1].next_in_sel = ae2;
        self.active_list[ae2].prev_in_sel = ae1;
    }

    fn add_new_intersect_node(&mut self, e1: usize, e2: usize, top_y: i64) {
        let a1 = self.e(e1);
        let a2 = self.e(e2);
        let mut ip = Point64::new(0, 0);
        if !get_line_intersect_pt(a1.bot, a1.top, a2.bot, a2.top, &mut ip) {
            ip = Point64::new(a1.curr_x, top_y); // parallel edges
        }

        if ip.y > self.bot_y || ip.y < top_y {
            // rounding errors have caused the intersection to be calculated
            // outside the scanbeam, so snap it back
            let abs_dx1 = a1.dx.abs();
            let abs_dx2 = a2.dx.abs();
            if abs_dx1 > 100.0 && abs_dx2 > 100.0 {
                if abs_dx1 > abs_dx2 {
                    ip = get_closest_point_on_segment(ip, a1.bot, a1.top);
                } else {
                    ip = get_closest_point_on_segment(ip, a2.bot, a2.top);
                }
            } else if abs_dx1 > 100.0 {
                ip = get_closest_point_on_segment(ip, a1.bot, a1.top);
            } else if abs_dx2 > 100.0 {
                ip = get_closest_point_on_segment(ip, a2.bot, a2.top);
            } else {
                if ip.y < top_y {
                    ip.y = top_y;
                } else {
                    ip.y = self.bot_y;
                }
                if abs_dx1 < abs_dx2 {
                    ip.x = top_x(a1.bot, a1.top, a1.dx, ip.y);
                } else {
                    ip.x = top_x(a2.bot, a2.top, a2.dx, ip.y);
                }
            }
        }
        self.intersect_nodes.push(IntersectNode {
            pt: ip,
            edge1: e1,
            edge2: e2,
        });
    }

    fn build_intersect_list(&mut self, top_y: i64) -> bool {
        if self.actives == NONE || self.e(self.actives).next_in_ael == NONE {
            return false;
        }

        // Calculate edge positions at the top of the current scanbeam, and from
        // this we will determine the intersections required to reach these new
        // positions.
        self.adjust_curr_x_and_copy_to_sel(top_y);

        // Find all edge intersections in the current scanbeam using a stable
        // merge sort that ensures only adjacent edges are intersecting.
        let mut left = self.sel;
        while left != NONE && self.e(left).jump != NONE {
            let mut prev_base = NONE;
            while left != NONE && self.e(left).jump != NONE {
                let mut curr_base = left;
                let mut right = self.e(left).jump;
                let mut l_end = right;
                let r_end = self.e(right).jump;
                self.active_list[left].jump = r_end;
                while left != l_end && right != r_end {
                    if self.e(right).curr_x < self.e(left).curr_x {
                        let mut tmp = self.e(right).prev_in_sel;
                        loop {
                            self.add_new_intersect_node(tmp, right, top_y);
                            if tmp == left {
                                break;
                            }
                            tmp = self.e(tmp).prev_in_sel;
                        }

                        tmp = right;
                        right = self.extract_from_sel(tmp);
                        l_end = right;
                        self.insert1_before2_in_sel(tmp, left);
                        if left == curr_base {
                            curr_base = tmp;
                            self.active_list[curr_base].jump = r_end;
                            if prev_base == NONE {
                                self.sel = curr_base;
                            } else {
                                self.active_list[prev_base].jump = curr_base;
                            }
                        }
                    } else {
                        left = self.e(left).next_in_sel;
                    }
                }
                prev_base = curr_base;
                left = r_end;
            }
            left = self.sel;
        }
        !self.intersect_nodes.is_empty()
    }

    fn edges_adjacent_in_ael(&self, node: &IntersectNode) -> bool {
        self.e(node.edge1).next_in_ael == node.edge2
            || self.e(node.edge1).prev_in_ael == node.edge2
    }

    fn process_intersect_list(&mut self) {
        // We now have a list of intersections required so that edges will be
        // correctly positioned at the top of the scanbeam. However, it's
        // important that edge intersections are processed from the bottom up,
        // but it's also crucial that intersections only occur between adjacent
        // edges.
        let mut nodes = std::mem::take(&mut self.intersect_nodes);
        std_sort(&mut nodes, &|a: &IntersectNode, b: &IntersectNode| {
            if a.pt.y == b.pt.y {
                a.pt.x < b.pt.x
            } else {
                a.pt.y > b.pt.y
            }
        });

        for i in 0..nodes.len() {
            if !self.edges_adjacent_in_ael(&nodes[i]) {
                let mut j = i + 1;
                while j < nodes.len() && !self.edges_adjacent_in_ael(&nodes[j]) {
                    j += 1;
                }
                if j < nodes.len() {
                    nodes.swap(i, j);
                }
            }
            let node = nodes[i];
            self.intersect_edges(node.edge1, node.edge2, node.pt);
            self.swap_positions_in_ael(node.edge1, node.edge2);
            self.active_list[node.edge1].curr_x = node.pt.x;
            self.active_list[node.edge2].curr_x = node.pt.x;
            self.check_join_left(node.edge2, node.pt, true);
            self.check_join_right(node.edge1, node.pt, true);
        }
        nodes.clear();
        self.intersect_nodes = nodes;
    }

    fn do_intersections(&mut self, top_y: i64) {
        if self.build_intersect_list(top_y) {
            self.process_intersect_list();
        }
    }

    // ---- horizontal joins ----------------------------------------------

    fn update_horz_segment(&mut self, hs_idx: usize) -> bool {
        let op = self.horz_seg_list[hs_idx].left_op;
        let outrec = self.get_real_out_rec(self.op(op).outrec);
        let outrec_has_edges = self.outrec_list[outrec].front_edge != NONE;
        let curr_y = self.op(op).pt.y;
        let mut op_prev = op;
        let mut op_next = op;

        if outrec_has_edges {
            let op_a = self.outrec_list[outrec].pts;
            let op_z = self.op(op_a).next;
            while op_prev != op_z && self.op(self.op(op_prev).prev).pt.y == curr_y {
                op_prev = self.op(op_prev).prev;
            }
            while op_next != op_a && self.op(self.op(op_next).next).pt.y == curr_y {
                op_next = self.op(op_next).next;
            }
        } else {
            while self.op(op_prev).prev != op_next && self.op(self.op(op_prev).prev).pt.y == curr_y
            {
                op_prev = self.op(op_prev).prev;
            }
            while self.op(op_next).next != op_prev && self.op(self.op(op_next).next).pt.y == curr_y
            {
                op_next = self.op(op_next).next;
            }
        }

        // SetHorzSegHeadingForward
        let heading_ok = {
            let px = self.op(op_prev).pt.x;
            let nx = self.op(op_next).pt.x;
            if px == nx {
                false
            } else {
                if px < nx {
                    self.horz_seg_list[hs_idx].left_op = op_prev;
                    self.horz_seg_list[hs_idx].right_op = op_next;
                    self.horz_seg_list[hs_idx].left_to_right = true;
                } else {
                    self.horz_seg_list[hs_idx].left_op = op_next;
                    self.horz_seg_list[hs_idx].right_op = op_prev;
                    self.horz_seg_list[hs_idx].left_to_right = false;
                }
                true
            }
        };

        let result = heading_ok && self.op(self.horz_seg_list[hs_idx].left_op).horz == NONE;
        if result {
            let lo = self.horz_seg_list[hs_idx].left_op;
            self.outpt_list[lo].horz = hs_idx;
        } else {
            self.horz_seg_list[hs_idx].right_op = NONE;
        }
        result
    }

    fn convert_horz_segs_to_joins(&mut self) {
        let mut j = 0usize;
        for i in 0..self.horz_seg_list.len() {
            if self.update_horz_segment(i) {
                j += 1;
            }
        }
        if j < 2 {
            return;
        }

        // stable_sort with HorzSegSorter
        let mut segs = std::mem::take(&mut self.horz_seg_list);
        let ops = &self.outpt_list;
        segs.sort_by(|hs1, hs2| {
            if hs1.right_op == NONE || hs2.right_op == NONE {
                // nulls last
                let a = hs1.right_op != NONE;
                let b = hs2.right_op != NONE;
                b.cmp(&a)
            } else {
                ops[hs1.left_op].pt.x.cmp(&ops[hs2.left_op].pt.x)
            }
        });
        self.horz_seg_list = segs;

        for hs1 in 0..(j - 1) {
            for hs2 in (hs1 + 1)..j {
                let s1 = self.horz_seg_list[hs1];
                let s2 = self.horz_seg_list[hs2];
                if self.op(s2.left_op).pt.x >= self.op(s1.right_op).pt.x
                    || s2.left_to_right == s1.left_to_right
                    || self.op(s2.right_op).pt.x <= self.op(s1.left_op).pt.x
                {
                    continue;
                }

                let curr_y = self.op(self.horz_seg_list[hs1].left_op).pt.y;
                if self.horz_seg_list[hs1].left_to_right {
                    loop {
                        let l1 = self.horz_seg_list[hs1].left_op;
                        let n = self.op(l1).next;
                        if self.op(n).pt.y == curr_y
                            && self.op(n).pt.x <= self.op(self.horz_seg_list[hs2].left_op).pt.x
                        {
                            self.horz_seg_list[hs1].left_op = n;
                        } else {
                            break;
                        }
                    }
                    loop {
                        let l2 = self.horz_seg_list[hs2].left_op;
                        let p = self.op(l2).prev;
                        if self.op(p).pt.y == curr_y
                            && self.op(p).pt.x <= self.op(self.horz_seg_list[hs1].left_op).pt.x
                        {
                            self.horz_seg_list[hs2].left_op = p;
                        } else {
                            break;
                        }
                    }
                    let op2 = self.duplicate_op(self.horz_seg_list[hs2].left_op, false);
                    let op1 = self.duplicate_op(self.horz_seg_list[hs1].left_op, true);
                    self.horz_join_list.push(HorzJoin { op1, op2 });
                } else {
                    loop {
                        let l1 = self.horz_seg_list[hs1].left_op;
                        let p = self.op(l1).prev;
                        if self.op(p).pt.y == curr_y
                            && self.op(p).pt.x <= self.op(self.horz_seg_list[hs2].left_op).pt.x
                        {
                            self.horz_seg_list[hs1].left_op = p;
                        } else {
                            break;
                        }
                    }
                    loop {
                        let l2 = self.horz_seg_list[hs2].left_op;
                        let n = self.op(l2).next;
                        if self.op(n).pt.y == curr_y
                            && self.op(n).pt.x <= self.op(self.horz_seg_list[hs1].left_op).pt.x
                        {
                            self.horz_seg_list[hs2].left_op = n;
                        } else {
                            break;
                        }
                    }
                    let op1 = self.duplicate_op(self.horz_seg_list[hs1].left_op, false);
                    let op2 = self.duplicate_op(self.horz_seg_list[hs2].left_op, true);
                    self.horz_join_list.push(HorzJoin {
                        op1: op2,
                        op2: op1,
                    });
                }
            }
        }
    }

    fn process_horz_joins(&mut self) {
        let joins = std::mem::take(&mut self.horz_join_list);
        for j in joins.iter() {
            let or1 = self.get_real_out_rec(self.op(j.op1).outrec);
            let mut or2 = self.get_real_out_rec(self.op(j.op2).outrec);

            let op1b = self.op(j.op1).next;
            let op2b = self.op(j.op2).prev;
            self.outpt_list[j.op1].next = j.op2;
            self.outpt_list[j.op2].prev = j.op1;
            self.outpt_list[op1b].prev = op2b;
            self.outpt_list[op2b].next = op1b;

            if or1 == or2 {
                // 'join' is really a split
                or2 = self.new_out_rec();
                self.outrec_list[or2].pts = op1b;
                self.fix_out_rec_pts(or2);

                // if or1->pts has moved to or2 then update or1->pts!
                let p = self.outrec_list[or1].pts;
                if self.op(p).outrec == or2 {
                    self.outrec_list[or1].pts = j.op1;
                    self.outpt_list[j.op1].outrec = or1;
                }
                self.outrec_list[or2].owner = or1;
            } else {
                self.outrec_list[or2].pts = NONE;
                self.outrec_list[or2].owner = or1;
            }
        }
    }
}

pub fn get_dx(pt1: Point64, pt2: Point64) -> f64 {

toolUseResult.newString:
// ---------------------------------------------------------------------------
// the sweep
// ---------------------------------------------------------------------------

impl Clipper {
    fn insert_local_minima_into_ael(&mut self, bot_y: i64) {
        while let Some(local_minima) = self.pop_local_minima(bot_y) {
            let lmv = self.lm(local_minima).vertex;
            let mut left_bound;
            let mut right_bound;

            if self.v(lmv).flags & VF_OPEN_START != 0 {
                left_bound = NONE;
            } else {
                let mut a = Active::new();
                a.bot = self.v(lmv).pt;
                a.curr_x = a.bot.x;
                a.wind_dx = -1;
                a.vertex_top = self.v(lmv).prev; // ie descending
                a.top = self.v(a.vertex_top).pt;
                a.outrec = NONE;
                a.local_min = local_minima;
                a.dx = get_dx(a.bot, a.top);
                self.active_list.push(a);
                left_bound = self.active_list.len() - 1;
            }

            if self.v(lmv).flags & VF_OPEN_END != 0 {
                right_bound = NONE;
            } else {
                let mut a = Active::new();
                a.bot = self.v(lmv).pt;
                a.curr_x = a.bot.x;
                a.wind_dx = 1;
                a.vertex_top = self.v(lmv).next; // ie ascending
                a.top = self.v(a.vertex_top).pt;
                a.outrec = NONE;
                a.local_min = local_minima;
                a.dx = get_dx(a.bot, a.top);
                self.active_list.push(a);
                right_bound = self.active_list.len() - 1;
            }

            // Currently LeftB is just the descending bound and RightB is the
            // ascending. Now if the LeftB isn't on the left of RightB then we
            // need to swap them.
            if left_bound != NONE && right_bound != NONE {
                if self.is_horizontal(left_bound) {
                    if self.is_heading_right_horz(left_bound) {
                        std::mem::swap(&mut left_bound, &mut right_bound);
                    }
                } else if self.is_horizontal(right_bound) {
                    if self.is_heading_left_horz(right_bound) {
                        std::mem::swap(&mut left_bound, &mut right_bound);
                    }
                } else if self.e(left_bound).dx < self.e(right_bound).dx {
                    std::mem::swap(&mut left_bound, &mut right_bound);
                }
            } else if left_bound == NONE {
                left_bound = right_bound;
                right_bound = NONE;
            }

            let contributing;
            self.active_list[left_bound].is_left_bound = true;
            self.insert_left_edge(left_bound);

            if self.is_open(left_bound) {
                self.set_wind_count_for_open_path_edge(left_bound);
                contributing = self.is_contributing_open(left_bound);
            } else {
                self.set_wind_count_for_closed_path_edge(left_bound);
                contributing = self.is_contributing_closed(left_bound);
            }

            if right_bound != NONE {
                self.active_list[right_bound].is_left_bound = false;
                self.active_list[right_bound].wind_cnt = self.e(left_bound).wind_cnt;
                self.active_list[right_bound].wind_cnt2 = self.e(left_bound).wind_cnt2;
                self.insert_right_edge(left_bound, right_bound);
                if contributing {
                    let bot = self.e(left_bound).bot;
                    self.add_local_min_poly(left_bound, right_bound, bot, true);
                    if !self.is_horizontal(left_bound) {
                        self.check_join_left(left_bound, bot, false);
                    }
                }

                while self.e(right_bound).next_in_ael != NONE
                    && self.is_valid_ael_order(self.e(right_bound).next_in_ael, right_bound)
                {
                    let nxt = self.e(right_bound).next_in_ael;
                    let bot = self.e(right_bound).bot;
                    self.intersect_edges(right_bound, nxt, bot);
                    self.swap_positions_in_ael(right_bound, nxt);
                }

                if self.is_horizontal(right_bound) {
                    self.push_horz(right_bound);
                } else {
                    let bot = self.e(right_bound).bot;
                    self.check_join_right(right_bound, bot, false);
                    let ty = self.e(right_bound).top.y;
                    self.insert_scanline(ty);
                }
            } else if contributing {
                let bot = self.e(left_bound).bot;
                self.start_open_path(left_bound, bot);
            }

            if self.is_horizontal(left_bound) {
                self.push_horz(left_bound);
            } else {
                let ty = self.e(left_bound).top.y;
                self.insert_scanline(ty);
            }
        }
    }

    fn push_horz(&mut self, e: usize) {
        self.active_list[e].next_in_sel = self.sel;
        self.sel = e;
    }

    fn pop_horz(&mut self) -> usize {
        let e = self.sel;
        if e == NONE {
            return NONE;
        }
        self.sel = self.e(e).next_in_sel;
        e
    }

    // open paths are never used by this program but the hooks are kept so the
    // control flow matches the reference implementation
    fn set_wind_count_for_open_path_edge(&mut self, _e: usize) {}
    fn is_contributing_open(&self, _e: usize) -> bool {
        false
    }
    fn start_open_path(&mut self, _e: usize, _pt: Point64) -> usize {
        NONE
    }

    fn check_join_left(&mut self, e: usize, pt: Point64, check_curr_x: bool) {
        let prev = self.e(e).prev_in_ael;
        if prev == NONE
            || !self.is_hot_edge(e)
            || !self.is_hot_edge(prev)
            || self.is_horizontal(e)
            || self.is_horizontal(prev)
            || self.is_open(e)
            || self.is_open(prev)
        {
            return;
        }
        if (pt.y < self.e(e).top.y + 2 || pt.y < self.e(prev).top.y + 2)
            && (self.e(e).bot.y > pt.y || self.e(prev).bot.y > pt.y)
        {
            return;
        }

        if check_curr_x {
            if perpendic_dist_from_line_sqrd(pt, self.e(prev).bot, self.e(prev).top) > 0.25 {
                return;
            }
        } else if self.e(e).curr_x != self.e(prev).curr_x {
            return;
        }
        if !is_collinear(self.e(e).top, pt, self.e(prev).top) {
            return;
        }

        let or_e = self.outrec_list[self.e(e).outrec].idx;
        let or_p = self.outrec_list[self.e(prev).outrec].idx;
        if or_e == or_p {
            self.add_local_max_poly(prev, e, pt);
        } else if or_e < or_p {
            self.join_outrec_paths(e, prev);
        } else {
            self.join_outrec_paths(prev, e);
        }
        self.active_list[prev].join_with = JoinWith::Right;
        self.active_list[e].join_with = JoinWith::Left;
    }

    fn check_join_right(&mut self, e: usize, pt: Point64, check_curr_x: bool) {
        let next = self.e(e).next_in_ael;
        if next == NONE
            || !self.is_hot_edge(e)
            || !self.is_hot_edge(next)
            || self.is_horizontal(e)
            || self.is_horizontal(next)
            || self.is_open(e)
            || self.is_open(next)
        {
            return;
        }
        if (pt.y < self.e(e).top.y + 2 || pt.y < self.e(next).top.y + 2)
            && (self.e(e).bot.y > pt.y || self.e(next).bot.y > pt.y)
        {
            return;
        }

        if check_curr_x {
            if perpendic_dist_from_line_sqrd(pt, self.e(next).bot, self.e(next).top) > 0.35 {
                return;
            }
        } else if self.e(e).curr_x != self.e(next).curr_x {
            return;
        }
        if !is_collinear(self.e(e).top, pt, self.e(next).top) {
            return;
        }

        let or_e = self.outrec_list[self.e(e).outrec].idx;
        let or_n = self.outrec_list[self.e(next).outrec].idx;
        if or_e == or_n {
            self.add_local_max_poly(e, next, pt);
        } else if or_e < or_n {
            self.join_outrec_paths(e, next);
        } else {
            self.join_outrec_paths(next, e);
        }
        self.active_list[e].join_with = JoinWith::Right;
        self.active_list[next].join_with = JoinWith::Left;
    }

    fn get_last_op(&self, hot_edge: usize) -> usize {
        let outrec = self.e(hot_edge).outrec;
        let result = self.outrec_list[outrec].pts;
        if self.outrec_list[outrec].front_edge == hot_edge {
            result
        } else {
            self.op(result).next
        }
    }

    fn add_trial_horz_join(&mut self, op: usize) {
        if !self.outrec_list[self.op(op).outrec].is_open {
            self.horz_seg_list.push(HorzSegment {
                left_op: op,
                right_op: NONE,
                left_to_right: true,
            });
        }
    }

    fn trim_horz(&mut self, horz: usize, preserve_collinear: bool) {
        let mut was_trimmed = false;
        let mut pt = self.v(self.next_vertex(horz)).pt;
        while pt.y == self.e(horz).top.y {
            // always trim 180 deg. spikes (in closed paths)
            // but otherwise break if preserveCollinear = true
            if preserve_collinear
                && (pt.x < self.e(horz).top.x) != (self.e(horz).bot.x < self.e(horz).top.x)
            {
                break;
            }
            self.active_list[horz].vertex_top = self.next_vertex(horz);
            self.active_list[horz].top = pt;
            was_trimmed = true;
            if self.is_maxima(horz) {
                break;
            }
            pt = self.v(self.next_vertex(horz)).pt;
        }
        if was_trimmed {
            self.set_dx(horz);
        }
    }

    fn update_edge_into_ael(&mut self, e: usize) {
        self.active_list[e].bot = self.e(e).top;
        self.active_list[e].vertex_top = self.next_vertex(e);
        self.active_list[e].top = self.v(self.e(e).vertex_top).pt;
        self.active_list[e].curr_x = self.e(e).bot.x;
        self.set_dx(e);

        if self.is_joined(e) {
            let bot = self.e(e).bot;
            self.split(e, bot);
        }

        if self.is_horizontal(e) {
            if !self.is_open(e) {
                let pc = self.preserve_collinear;
                self.trim_horz(e, pc);
            }
            return;
        }
        let ty = self.e(e).top.y;
        self.insert_scanline(ty);
        let bot = self.e(e).bot;
        self.check_join_left(e, bot, false);
        self.check_join_right(e, bot, true);
    }

    fn reset_horz_direction(&self, horz: usize, vertex_max: usize) -> (bool, i64, i64) {
        let h = self.e(horz);
        if h.bot.x == h.top.x {
            // the horizontal edge is going nowhere ...
            let left_x = h.curr_x;
            let right_x = h.curr_x;
            let mut e = h.next_in_ael;
            while e != NONE && self.e(e).vertex_top != vertex_max {
                e = self.e(e).next_in_ael;
            }
            (e != NONE, left_x, right_x)
        } else if h.curr_x < h.top.x {
            (true, h.curr_x, h.top.x)
        } else {
            (false, h.top.x, h.curr_x)
        }
    }

    fn do_horizontal(&mut self, horz: usize) {
        let horz_is_open = self.is_open(horz);
        let y = self.e(horz).bot.y;
        let vertex_max = if horz_is_open {
            self.get_curr_y_maxima_vertex_open(horz)
        } else {
            self.get_curr_y_maxima_vertex(horz)
        };

        let (mut is_left_to_right, mut left_x, mut right_x) =
            self.reset_horz_direction(horz, vertex_max);

        if self.is_hot_edge(horz) {
            let cx = self.e(horz).curr_x;
            let op = self.add_out_pt(horz, Point64::new(cx, y));
            self.add_trial_horz_join(op);
        }

        loop {
            // loop through consecutive horizontal edges
            let mut e = if is_left_to_right {
                self.e(horz).next_in_ael
            } else {
                self.e(horz).prev_in_ael
            };

            while e != NONE {
                if self.e(e).vertex_top == vertex_max {
                    if self.is_hot_edge(horz) && self.is_joined(e) {
                        let top = self.e(e).top;
                        self.split(e, top);
                    }
                    if self.is_hot_edge(horz) {
                        while self.e(horz).vertex_top != vertex_max {
                            let top = self.e(horz).top;
                            self.add_out_pt(horz, top);
                            self.update_edge_into_ael(horz);
                        }
                        let top = self.e(horz).top;
                        if is_left_to_right {
                            self.add_local_max_poly(horz, e, top);
                        } else {
                            self.add_local_max_poly(e, horz, top);
                        }
                    }
                    self.delete_from_ael(e);
                    self.delete_from_ael(horz);
                    return;
                }

                // if horzEdge is a maxima, keep going until we reach its maxima
                // pair, otherwise check for break conditions
                if vertex_max != self.e(horz).vertex_top || self.is_open_end(horz) {
                    // stop when 'e' is beyond the end of the horizontal line
                    if is_left_to_right && self.e(e).curr_x > right_x {
                        break;
                    }
                    if !is_left_to_right && self.e(e).curr_x < left_x {
                        break;
                    }

                    if self.e(e).curr_x == self.e(horz).top.x && !self.is_horizontal(e) {
                        let pt = self.v(self.next_vertex(horz)).pt;
                        let ea = self.e(e);
                        if is_left_to_right {
                            if self.is_open(e)
                                && !self.is_same_poly_type(e, horz)
                                && !self.is_hot_edge(e)
                            {
                                if top_x(ea.bot, ea.top, ea.dx, pt.y) > pt.x {
                                    break;
                                }
                            } else if top_x(ea.bot, ea.top, ea.dx, pt.y) >= pt.x {
                                break;
                            }
                        } else if self.is_open(e)
                            && !self.is_same_poly_type(e, horz)
                            && !self.is_hot_edge(e)
                        {
                            if top_x(ea.bot, ea.top, ea.dx, pt.y) < pt.x {
                                break;
                            }
                        } else if top_x(ea.bot, ea.top, ea.dx, pt.y) <= pt.x {
                            break;
                        }
                    }
                }

                let pt = Point64::new(self.e(e).curr_x, self.e(horz).bot.y);

                if is_left_to_right {
                    self.intersect_edges(horz, e, pt);
                    self.swap_positions_in_ael(horz, e);
                    self.check_join_left(e, pt, false);
                    self.active_list[horz].curr_x = self.e(e).curr_x;
                    e = self.e(horz).next_in_ael;
                } else {
                    self.intersect_edges(e, horz, pt);
                    self.swap_positions_in_ael(e, horz);
                    self.check_join_right(e, pt, false);
                    self.active_list[horz].curr_x = self.e(e).curr_x;
                    e = self.e(horz).prev_in_ael;
                }

                if self.is_hot_edge(horz) {
                    let op = self.get_last_op(horz);
                    self.add_trial_horz_join(op);
                }
            }

            // we've reached the end of this horizontal
            if horz_is_open && self.is_open_end(horz) {
                if self.is_hot_edge(horz) {
                    let top = self.e(horz).top;
                    self.add_out_pt(horz, top);
                    let o = self.e(horz).outrec;
                    if self.is_front(horz) {
                        self.outrec_list[o].front_edge = NONE;
                    } else {
                        self.outrec_list[o].back_edge = NONE;
                    }
                    self.active_list[horz].outrec = NONE;
                }
                self.delete_from_ael(horz);
                return;
            }

            if self.v(self.next_vertex(horz)).pt.y != self.e(horz).top.y {
                break;
            }

            // still more horizontals in bound to process ...
            if self.is_hot_edge(horz) {
                let top = self.e(horz).top;
                self.add_out_pt(horz, top);
            }
            self.update_edge_into_ael(horz);

            let r = self.reset_horz_direction(horz, vertex_max);
            is_left_to_right = r.0;
            left_x = r.1;
            right_x = r.2;
            let _ = (left_x, right_x);
        }

        if self.is_hot_edge(horz) {
            let top = self.e(horz).top;
            let op = self.add_out_pt(horz, top);
            self.add_trial_horz_join(op);
        }
        self.update_edge_into_ael(horz);
    }

    fn get_curr_y_maxima_vertex_open(&self, e: usize) -> usize {
        let a = self.e(e);
        let mut result = a.vertex_top;
        if a.wind_dx > 0 {
            while self.v(self.v(result).next).pt.y == self.v(result).pt.y {
                if self.v(result).flags & (VF_OPEN_END | VF_LOCAL_MAX) != 0 {
                    break;
                }
                result = self.v(result).next;
            }
        } else {
            while self.v(self.v(result).prev).pt.y == self.v(result).pt.y {
                if self.v(result).flags & (VF_OPEN_END | VF_LOCAL_MAX) != 0 {
                    break;
                }
                result = self.v(result).prev;
            }
        }
        if !self.is_maxima_v(result) {
            NONE
        } else {
            result
        }
    }

    fn do_top_of_scanbeam(&mut self, y: i64) {
        self.sel = NONE; // sel_ is reused to flag horizontals (see push_horz)
        let mut e = self.actives;
        while e != NONE {
            // nb: 'e' will never be horizontal here
            if self.e(e).top.y == y {
                self.active_list[e].curr_x = self.e(e).top.x;
                if self.is_maxima(e) {
                    e = self.do_maxima(e); // TOP OF BOUND (MAXIMA)
                    continue;
                }
                // INTERMEDIATE VERTEX ...
                if self.is_hot_edge(e) {
                    let top = self.e(e).top;
                    self.add_out_pt(e, top);
                }
                self.update_edge_into_ael(e);
                if self.is_horizontal(e) {
                    self.push_horz(e);
                }
            } else {
                let a = self.e(e);
                self.active_list[e].curr_x = top_x(a.bot, a.top, a.dx, y);
            }
            e = self.e(e).next_in_ael;
        }
    }

    fn do_maxima(&mut self, e: usize) -> usize {
        let prev_e = self.e(e).prev_in_ael;
        let mut next_e = self.e(e).next_in_ael;

        if self.is_open_end(e) {
            if self.is_hot_edge(e) {
                let top = self.e(e).top;
                self.add_out_pt(e, top);
            }
            if !self.is_horizontal(e) {
                if self.is_hot_edge(e) {
                    let o = self.e(e).outrec;
                    if self.is_front(e) {
                        self.outrec_list[o].front_edge = NONE;
                    } else {
                        self.outrec_list[o].back_edge = NONE;
                    }
                    self.active_list[e].outrec = NONE;
                }
                self.delete_from_ael(e);
            }
            return next_e;
        }

        let max_pair = self.get_maxima_pair(e);
        if max_pair == NONE {
            return next_e; // e's maxima pair is horizontal
        }

        if self.is_joined(e) {
            let top = self.e(e).top;
            self.split(e, top);
        }
        if self.is_joined(max_pair) {
            let top = self.e(max_pair).top;
            self.split(max_pair, top);
        }

        // only non-horizontal maxima here.
        // process any edges between maxima pair ...
        while next_e != max_pair {
            let top = self.e(e).top;
            self.intersect_edges(e, next_e, top);
            self.swap_positions_in_ael(e, next_e);
            next_e = self.e(e).next_in_ael;
        }

        if self.is_hot_edge(e) {
            let top = self.e(e).top;
            self.add_local_max_poly(e, max_pair, top);
        }

        self.delete_from_ael(e);
        self.delete_from_ael(max_pair);
        if prev_e != NONE {
            self.e(prev_e).next_in_ael
        } else {
            self.actives
        }
    }

    fn adjust_curr_x_and_copy_to_sel(&mut self, top_y: i64) {
        let mut e = self.actives;
        self.sel = e;
        while e != NONE {
            let a = self.e(e);
            self.active_list[e].prev_in_sel = a.prev_in_ael;
            self.active_list[e].next_in_sel = a.next_in_ael;
            self.active_list[e].jump = a.next_in_ael;
            if a.join_with == JoinWith::Left {
                self.active_list[e].curr_x = self.e(a.prev_in_ael).curr_x;
            } else {
                self.active_list[e].curr_x = top_x(a.bot, a.top, a.dx, top_y);
            }
            e = self.e(e).next_in_ael;
        }
    }

    fn extract_from_sel(&mut self, ae: usize) -> usize {
        let res = self.e(ae).next_in_sel;
        let prev = self.e(ae).prev_in_sel;
        if res != NONE {
            self.active_list[res].prev_in_sel = prev;
        }
        if prev != NONE {
            self.active_list[prev].next_in_sel = res;
        }
        res
    }

    fn insert1_before2_in_sel(&mut self, ae1: usize, ae2: usize) {
        let prev = self.e(ae2).prev_in_sel;
        self.active_list[ae1].prev_in_sel = prev;
        if prev != NONE {
            self.active_list[prev].next_in_sel = ae1;
        }
        self.active_list[ae1].next_in_sel = ae2;
        self.active_list[ae2].prev_in_sel = ae1;
    }

    fn add_new_intersect_node(&mut self, e1: usize, e2: usize, top_y: i64) {
        let a1 = self.e(e1);
        let a2 = self.e(e2);
        let mut ip = Point64::new(0, 0);
        if !get_line_intersect_pt(a1.bot, a1.top, a2.bot, a2.top, &mut ip) {
            ip = Point64::new(a1.curr_x, top_y); // parallel edges
        }

        if ip.y > self.bot_y || ip.y < top_y {
            // rounding errors have caused the intersection to be calculated
            // outside the scanbeam, so snap it back
            let abs_dx1 = a1.dx.abs();
            let abs_dx2 = a2.dx.abs();
            if abs_dx1 > 100.0 && abs_dx2 > 100.0 {
                if abs_dx1 > abs_dx2 {
                    ip = get_closest_point_on_segment(ip, a1.bot, a1.top);
                } else {
                    ip = get_closest_point_on_segment(ip, a2.bot, a2.top);
                }
            } else if abs_dx1 > 100.0 {
                ip = get_closest_point_on_segment(ip, a1.bot, a1.top);
            } else if abs_dx2 > 100.0 {
                ip = get_closest_point_on_segment(ip, a2.bot, a2.top);
            } else {
                if ip.y < top_y {
                    ip.y = top_y;
                } else {
                    ip.y = self.bot_y;
                }
                if abs_dx1 < abs_dx2 {
                    ip.x = top_x(a1.bot, a1.top, a1.dx, ip.y);
                } else {
                    ip.x = top_x(a2.bot, a2.top, a2.dx, ip.y);
                }
            }
        }
        self.intersect_nodes.push(IntersectNode {
            pt: ip,
            edge1: e1,
            edge2: e2,
        });
    }

    fn build_intersect_list(&mut self, top_y: i64) -> bool {
        if self.actives == NONE || self.e(self.actives).next_in_ael == NONE {
            return false;
        }

        // Calculate edge positions at the top of the current scanbeam, and from
        // this we will determine the intersections required to reach these new
        // positions.
        self.adjust_curr_x_and_copy_to_sel(top_y);

        // Find all edge intersections in the current scanbeam using a stable
        // merge sort that ensures only adjacent edges are intersecting.
        let mut left = self.sel;
        while left != NONE && self.e(left).jump != NONE {
            let mut prev_base = NONE;
            while left != NONE && self.e(left).jump != NONE {
                let mut curr_base = left;
                let mut right = self.e(left).jump;
                let mut l_end = right;
                let r_end = self.e(right).jump;
                self.active_list[left].jump = r_end;
                while left != l_end && right != r_end {
                    if self.e(right).curr_x < self.e(left).curr_x {
                        let mut tmp = self.e(right).prev_in_sel;
                        loop {
                            self.add_new_intersect_node(tmp, right, top_y);
                            if tmp == left {
                                break;
                            }
                            tmp = self.e(tmp).prev_in_sel;
                        }

                        tmp = right;
                        right = self.extract_from_sel(tmp);
                        l_end = right;
                        self.insert1_before2_in_sel(tmp, left);
                        if left == curr_base {
                            curr_base = tmp;
                            self.active_list[curr_base].jump = r_end;
                            if prev_base == NONE {
                                self.sel = curr_base;
                            } else {
                                self.active_list[prev_base].jump = curr_base;
                            }
                        }
                    } else {
                        left = self.e(left).next_in_sel;
                    }
                }
                prev_base = curr_base;
                left = r_end;
            }
            left = self.sel;
        }
        !self.intersect_nodes.is_empty()
    }

    fn edges_adjacent_in_ael(&self, node: &IntersectNode) -> bool {
        self.e(node.edge1).next_in_ael == node.edge2
            || self.e(node.edge1).prev_in_ael == node.edge2
    }

    fn process_intersect_list(&mut self) {
        // We now have a list of intersections required so that edges will be
        // correctly positioned at the top of the scanbeam. However, it's
        // important that edge intersections are processed from the bottom up,
        // but it's also crucial that intersections only occur between adjacent
        // edges.
        let mut nodes = std::mem::take(&mut self.intersect_nodes);
        std_sort(&mut nodes, &|a: &IntersectNode, b: &IntersectNode| {
            if a.pt.y == b.pt.y {
                a.pt.x < b.pt.x
            } else {
                a.pt.y > b.pt.y
            }
        });

        for i in 0..nodes.len() {
            if !self.edges_adjacent_in_ael(&nodes[i]) {
                let mut j = i + 1;
                while j < nodes.len() && !self.edges_adjacent_in_ael(&nodes[j]) {
                    j += 1;
                }
                if j < nodes.len() {
                    nodes.swap(i, j);
                }
            }
            let node = nodes[i];
            self.intersect_edges(node.edge1, node.edge2, node.pt);
            self.swap_positions_in_ael(node.edge1, node.edge2);
            self.active_list[node.edge1].curr_x = node.pt.x;
            self.active_list[node.edge2].curr_x = node.pt.x;
            self.check_join_left(node.edge2, node.pt, true);
            self.check_join_right(node.edge1, node.pt, true);
        }
        nodes.clear();
        self.intersect_nodes = nodes;
    }

    fn do_intersections(&mut self, top_y: i64) {
        if self.build_intersect_list(top_y) {
            self.process_intersect_list();
        }
    }

    // ---- horizontal joins ----------------------------------------------

    fn update_horz_segment(&mut self, hs_idx: usize) -> bool {
        let op = self.horz_seg_list[hs_idx].left_op;
        let outrec = self.get_real_out_rec(self.op(op).outrec);
        let outrec_has_edges = self.outrec_list[outrec].front_edge != NONE;
        let curr_y = self.op(op).pt.y;
        let mut op_prev = op;
        let mut op_next = op;

        if outrec_has_edges {
            let op_a = self.outrec_list[outrec].pts;
            let op_z = self.op(op_a).next;
            while op_prev != op_z && self.op(self.op(op_prev).prev).pt.y == curr_y {
                op_prev = self.op(op_prev).prev;
            }
            while op_next != op_a && self.op(self.op(op_next).next).pt.y == curr_y {
                op_next = self.op(op_next).next;
            }
        } else {
            while self.op(op_prev).prev != op_next && self.op(self.op(op_prev).prev).pt.y == curr_y
            {
                op_prev = self.op(op_prev).prev;
            }
            while self.op(op_next).next != op_prev && self.op(self.op(op_next).next).pt.y == curr_y
            {
                op_next = self.op(op_next).next;
            }
        }

        // SetHorzSegHeadingForward
        let heading_ok = {
            let px = self.op(op_prev).pt.x;
            let nx = self.op(op_next).pt.x;
            if px == nx {
                false
            } else {
                if px < nx {
                    self.horz_seg_list[hs_idx].left_op = op_prev;
                    self.horz_seg_list[hs_idx].right_op = op_next;
                    self.horz_seg_list[hs_idx].left_to_right = true;
                } else {
                    self.horz_seg_list[hs_idx].left_op = op_next;
                    self.horz_seg_list[hs_idx].right_op = op_prev;
                    self.horz_seg_list[hs_idx].left_to_right = false;
                }
                true
            }
        };

        let result = heading_ok && self.op(self.horz_seg_list[hs_idx].left_op).horz == NONE;
        if result {
            let lo = self.horz_seg_list[hs_idx].left_op;
            self.outpt_list[lo].horz = hs_idx;
        } else {
            self.horz_seg_list[hs_idx].right_op = NONE;
        }
        result
    }

    fn convert_horz_segs_to_joins(&mut self) {
        let mut j = 0usize;
        for i in 0..self.horz_seg_list.len() {
            if self.update_horz_segment(i) {
                j += 1;
            }
        }
        if j < 2 {
            return;
        }

        // stable_sort with HorzSegSorter
        let mut segs = std::mem::take(&mut self.horz_seg_list);
        let ops = &self.outpt_list;
        segs.sort_by(|hs1, hs2| {
            if hs1.right_op == NONE || hs2.right_op == NONE {
                // nulls last
                let a = hs1.right_op != NONE;
                let b = hs2.right_op != NONE;
                b.cmp(&a)
            } else {
                ops[hs1.left_op].pt.x.cmp(&ops[hs2.left_op].pt.x)
            }
        });
        self.horz_seg_list = segs;

        for hs1 in 0..(j - 1) {
            for hs2 in (hs1 + 1)..j {
                let s1 = self.horz_seg_list[hs1];
                let s2 = self.horz_seg_list[hs2];
                if self.op(s2.left_op).pt.x >= self.op(s1.right_op).pt.x
                    || s2.left_to_right == s1.left_to_right
                    || self.op(s2.right_op).pt.x <= self.op(s1.left_op).pt.x
                {
                    continue;
                }

                let curr_y = self.op(self.horz_seg_list[hs1].left_op).pt.y;
                if self.horz_seg_list[hs1].left_to_right {
                    loop {
                        let l1 = self.horz_seg_list[hs1].left_op;
                        let n = self.op(l1).next;
                        if self.op(n).pt.y == curr_y
                            && self.op(n).pt.x <= self.op(self.horz_seg_list[hs2].left_op).pt.x
                        {
                            self.horz_seg_list[hs1].left_op = n;
                        } else {
                            break;
                        }
                    }
                    loop {
                        let l2 = self.horz_seg_list[hs2].left_op;
                        let p = self.op(l2).prev;
                        if self.op(p).pt.y == curr_y
                            && self.op(p).pt.x <= self.op(self.horz_seg_list[hs1].left_op).pt.x
                        {
                            self.horz_seg_list[hs2].left_op = p;
                        } else {
                            break;
                        }
                    }
                    let op2 = self.duplicate_op(self.horz_seg_list[hs2].left_op, false);
                    let op1 = self.duplicate_op(self.horz_seg_list[hs1].left_op, true);
                    self.horz_join_list.push(HorzJoin { op1, op2 });
                } else {
                    loop {
                        let l1 = self.horz_seg_list[hs1].left_op;
                        let p = self.op(l1).prev;
                        if self.op(p).pt.y == curr_y
                            && self.op(p).pt.x <= self.op(self.horz_seg_list[hs2].left_op).pt.x
                        {
                            self.horz_seg_list[hs1].left_op = p;
                        } else {
                            break;
                        }
                    }
                    loop {
                        let l2 = self.horz_seg_list[hs2].left_op;
                        let n = self.op(l2).next;
                        if self.op(n).pt.y == curr_y
                            && self.op(n).pt.x <= self.op(self.horz_seg_list[hs1].left_op).pt.x
                        {
                            self.horz_seg_list[hs2].left_op = n;
                        } else {
                            break;
                        }
                    }
                    let op1 = self.duplicate_op(self.horz_seg_list[hs1].left_op, false);
                    let op2 = self.duplicate_op(self.horz_seg_list[hs2].left_op, true);
                    self.horz_join_list.push(HorzJoin {
                        op1: op2,
                        op2: op1,
                    });
                }
            }
        }
    }

    fn process_horz_joins(&mut self) {
        let joins = std::mem::take(&mut self.horz_join_list);
        for j in joins.iter() {
            let or1 = self.get_real_out_rec(self.op(j.op1).outrec);
            let mut or2 = self.get_real_out_rec(self.op(j.op2).outrec);

            let op1b = self.op(j.op1).next;
            let op2b = self.op(j.op2).prev;
            self.outpt_list[j.op1].next = j.op2;
            self.outpt_list[j.op2].prev = j.op1;
            self.outpt_list[op1b].prev = op2b;
            self.outpt_list[op2b].next = op1b;

            if or1 == or2 {
                // 'join' is really a split
                or2 = self.new_out_rec();
                self.outrec_list[or2].pts = op1b;
                self.fix_out_rec_pts(or2);

                // if or1->pts has moved to or2 then update or1->pts!
                let p = self.outrec_list[or1].pts;
