// ---------------------------------------------------------------------------
// post-sweep cleanup and solution building
// ---------------------------------------------------------------------------

impl Clipper {
    fn dispose_out_pts(&mut self, outrec: usize) {
        self.outrec_list[outrec].pts = NONE;
    }

    fn clean_collinear(&mut self, outrec_in: usize) {
        let outrec = self.get_real_out_rec(outrec_in);
        if outrec == NONE || self.outrec_list[outrec].is_open {
            return;
        }
        if !self.is_valid_closed_path(self.outrec_list[outrec].pts) {
            self.dispose_out_pts(outrec);
            return;
        }

        let mut start_op = self.outrec_list[outrec].pts;
        let mut op2 = start_op;
        loop {
            let prev = self.op(op2).prev;
            let next = self.op(op2).next;
            if is_collinear(self.op(prev).pt, self.op(op2).pt, self.op(next).pt)
                && (self.op(op2).pt == self.op(prev).pt
                    || self.op(op2).pt == self.op(next).pt
                    || !self.preserve_collinear
                    || dot_product(self.op(prev).pt, self.op(op2).pt, self.op(next).pt) < 0.0)
            {
                if op2 == self.outrec_list[outrec].pts {
                    self.outrec_list[outrec].pts = prev;
                }
                op2 = self.dispose_out_pt(op2);
                if !self.is_valid_closed_path(op2) {
                    self.dispose_out_pts(outrec);
                    return;
                }
                start_op = op2;
                continue;
            }
            op2 = self.op(op2).next;
            if op2 == start_op {
                break;
            }
        }
        self.fix_self_intersects(outrec);
    }

    fn fix_self_intersects(&mut self, outrec: usize) {
        let mut op2 = self.outrec_list[outrec].pts;
        loop {
            // triangles can't self-intersect
            let prev = self.op(op2).prev;
            let next = self.op(op2).next;
            let next2 = self.op(next).next;
            if prev == next2 {
                break;
            }
            if segments_intersect(
                self.op(prev).pt,
                self.op(op2).pt,
                self.op(next).pt,
                self.op(next2).pt,
                false,
            ) {
                let pts = self.outrec_list[outrec].pts;
                if op2 == pts || next == pts {
                    self.outrec_list[outrec].pts = self.op(pts).prev;
                }
                self.do_split_op(outrec, op2);
                if self.outrec_list[outrec].pts == NONE {
                    break;
                }
                op2 = self.outrec_list[outrec].pts;
                continue;
            }
            op2 = self.op(op2).next;
            if op2 == self.outrec_list[outrec].pts {
                break;
            }
        }
    }

    fn do_split_op(&mut self, outrec: usize, split_op: usize) {
        // split_op.prev -> split_op and split_op.next -> split_op.next.next
        // are intersecting
        let prev_op = self.op(split_op).prev;
        let next_op = self.op(split_op).next;
        let next_next_op = self.op(next_op).next;
        self.outrec_list[outrec].pts = prev_op;

        let mut ip = Point64::new(0, 0);
        get_line_intersect_pt(
            self.op(prev_op).pt,
            self.op(split_op).pt,
            self.op(next_op).pt,
            self.op(next_next_op).pt,
            &mut ip,
        );

        let area1 = self.area_op(self.outrec_list[outrec].pts);
        let abs_area1 = area1.abs();

        if abs_area1 < 2.0 {
            self.dispose_out_pts(outrec);
            return;
        }

        let area2 = area_triangle(ip, self.op(split_op).pt, self.op(next_op).pt);
        let abs_area2 = area2.abs();

        // de-link split_op and split_op.next from the path while inserting the
        // intersection point
        if ip == self.op(prev_op).pt || ip == self.op(next_next_op).pt {
            self.outpt_list[next_next_op].prev = prev_op;
            self.outpt_list[prev_op].next = next_next_op;
        } else {
            let new_op2 = self.new_out_pt(ip, outrec);
            self.outpt_list[new_op2].prev = prev_op;
            self.outpt_list[new_op2].next = next_next_op;
            self.outpt_list[next_next_op].prev = new_op2;
            self.outpt_list[prev_op].next = new_op2;
        }

        // area1 is the path's area *before* splitting, whereas area2 is the area
        // of the triangle containing split_op and split_op.next
        if abs_area2 > 1.0 && (abs_area2 > abs_area1 || ((area2 > 0.0) == (area1 > 0.0))) {
            let new_outrec = self.new_out_rec();
            self.outrec_list[new_outrec].owner = self.outrec_list[outrec].owner;
            self.outpt_list[split_op].outrec = new_outrec;
            self.outpt_list[next_op].outrec = new_outrec;

            let new_op = self.new_out_pt(ip, new_outrec);
            self.outpt_list[new_op].prev = next_op;
            self.outpt_list[new_op].next = split_op;
            self.outrec_list[new_outrec].pts = new_op;
            self.outpt_list[split_op].prev = new_op;
            self.outpt_list[next_op].next = new_op;
        }
    }

    fn is_very_small_triangle(&self, op: usize) -> bool {
        let next = self.op(op).next;
        let prev = self.op(op).prev;
        self.op(next).next == prev
            && (pts_really_close(self.op(prev).pt, self.op(next).pt)
                || pts_really_close(self.op(op).pt, self.op(next).pt)
                || pts_really_close(self.op(op).pt, self.op(prev).pt))
    }

    fn build_path(&self, op_in: usize, reverse: bool, is_open: bool, path: &mut Path64) -> bool {
        let mut op = op_in;
        if self.op(op).next == op || (!is_open && self.op(op).next == self.op(op).prev) {
            return false;
        }
        path.clear();
        let mut last_pt;
        let mut op2;
        if reverse {
            last_pt = self.op(op).pt;
            op2 = self.op(op).prev;
        } else {
            op = self.op(op).next;
            last_pt = self.op(op).pt;
            op2 = self.op(op).next;
        }
        path.push(last_pt);

        while op2 != op {
            if self.op(op2).pt != last_pt {
                last_pt = self.op(op2).pt;
                path.push(last_pt);
            }
            if reverse {
                op2 = self.op(op2).prev;
            } else {
                op2 = self.op(op2).next;
            }
        }

        if path.len() == 3 && self.is_very_small_triangle(op2) {
            return false;
        }
        true
    }

    fn build_paths(&mut self, solution_closed: &mut Paths64, solution_open: Option<&mut Paths64>) {
        solution_closed.clear();
        let mut open = solution_open;
        if let Some(o) = open.as_mut() {
            o.clear();
        }

        // nb: outrec_list_ can grow while this loop runs (clean_collinear can
        // add new records via do_split_op)
        let mut i = 0;
        while i < self.outrec_list.len() {
            let outrec = i;
            i += 1;
            if self.outrec_list[outrec].pts == NONE {
                continue;
            }
            let mut path: Path64 = Vec::new();
            if self.outrec_list[outrec].is_open {
                if let Some(o) = open.as_mut() {
                    if self.build_path(
                        self.outrec_list[outrec].pts,
                        self.reverse_solution,
                        true,
                        &mut path,
                    ) {
                        o.push(path);
                    }
                }
            } else {
                self.clean_collinear(outrec);
                // closed paths should always return a Positive orientation
                // except when reverse_solution is true
                if self.outrec_list[outrec].pts == NONE {
                    continue;
                }
                if self.build_path(
                    self.outrec_list[outrec].pts,
                    self.reverse_solution,
                    false,
                    &mut path,
                ) {
                    solution_closed.push(path);
                }
            }
        }
    }

    fn execute_internal(&mut self, ct: ClipType, fillrule: FillRule, use_polytrees: bool) -> bool {
        self.cliptype = ct;
        self.fillrule = fillrule;
        self.using_polytree = use_polytrees;
        self.reset();
        if ct == ClipType::NoClip {
            return true;
        }
        let mut y = match self.pop_scanline() {
            Some(v) => v,
            None => return true,
        };

        while self.succeeded {
            self.insert_local_minima_into_ael(y);
            loop {
                let e = self.pop_horz();
                if e == NONE {
                    break;
                }
                self.do_horizontal(e);
            }
            if !self.horz_seg_list.is_empty() {
                self.convert_horz_segs_to_joins();
                self.horz_seg_list.clear();
            }
            self.bot_y = y; // bot_y_ == bottom of scanbeam
            y = match self.pop_scanline() {
                Some(v) => v,
                None => break,
            };
            self.do_intersections(y);
            self.do_top_of_scanbeam(y);
            loop {
                let e = self.pop_horz();
                if e == NONE {
                    break;
                }
                self.do_horizontal(e);
            }
        }
        if self.succeeded {
            self.process_horz_joins();
        }
        self.succeeded
    }

    pub fn execute(&mut self, ct: ClipType, fillrule: FillRule, closed: &mut Paths64) -> bool {
        closed.clear();
        if self.execute_internal(ct, fillrule, false) {
            self.build_paths(closed, None);
        }
        self.succeeded
    }

    pub fn set_preserve_collinear(&mut self, val: bool) {
        self.preserve_collinear = val;
    }
    pub fn set_reverse_solution(&mut self, val: bool) {
        self.reverse_solution = val;
    }
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

pub fn boolean_op(
    cliptype: ClipType,
    fillrule: FillRule,
    subjects: &[Path64],
    clips: &[Path64],
) -> Paths64 {
    let mut c = Clipper::new();
    c.add_paths(subjects, PathType::Subject, false);
    c.add_paths(clips, PathType::Clip, false);
    let mut solution = Vec::new();
    c.execute(cliptype, fillrule, &mut solution);
    solution
}

pub fn union_paths(subjects: &[Path64], fillrule: FillRule) -> Paths64 {
    let mut c = Clipper::new();
    c.add_paths(subjects, PathType::Subject, false);
    let mut solution = Vec::new();
    c.execute(ClipType::Union, fillrule, &mut solution);
    solution
}

pub fn intersect(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Intersection, fillrule, subjects, clips)
}

pub fn difference(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Difference, fillrule, subjects, clips)
}

pub fn xor_paths(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Xor, fillrule, subjects, clips)
}

pub fn pts_really_close(pt1: Point64, pt2: Point64) -> bool {
    (pt1.x - pt2.x).abs() < 2 && (pt1.y - pt2.y).abs() < 2
}

