    fn build_path(&self, op_in: usize, reverse: bool, is_open: bool, path: &mut Path64) -> bool {
        let mut op = op_in;
        if self.op(op).next == op || (!is_open && self.op(op).next == self.op(op).prev) {
            return false;
        }
        path.clear();
        let mut last_pt;
        let mut op2;
        if reverse {
            last_pt = self.op(op).pt;
            op2 = self.op(op).prev;
        } else {
            op = self.op(op).next;
            last_pt = self.op(op).pt;
            op2 = self.op(op).next;
        }
        path.push(last_pt);

        while op2 != op {
            if self.op(op2).pt != last_pt {
                last_pt = self.op(op2).pt;
                path.push(last_pt);
            }
            if reverse {
                op2 = self.op(op2).prev;
            } else {
                op2 = self.op(op2).next;
            }
        }

        if path.len() == 3 && self.is_very_small_triangle(op2) {
            return false;
        }
        true
    }

    fn build_paths(&mut self, solution_closed: &mut Paths64, solution_open: Option<&mut Paths64>) {
        solution_closed.clear();
        let mut open = solution_open;
        if let Some(o) = open.as_mut() {
            o.clear();
        }

        // nb: outrec_list_ can grow while this loop runs (clean_collinear can
        // add new records via do_split_op)
        let mut i = 0;
        while i < self.outrec_list.len() {
            let outrec = i;
            i += 1;
            if self.outrec_list[outrec].pts == NONE {
                continue;
            }
            let mut path: Path64 = Vec::new();
            if self.outrec_list[outrec].is_open {
                if let Some(o) = open.as_mut() {
                    if self.build_path(
                        self.outrec_list[outrec].pts,
                        self.reverse_solution,
                        true,
                        &mut path,
                    ) {
                        o.push(path);
                    }
                }
            } else {
                self.clean_collinear(outrec);
                // closed paths should always return a Positive orientation
                // except when reverse_solution is true
                if self.outrec_list[outrec].pts == NONE {
                    continue;
                }
                if self.build_path(
                    self.outrec_list[outrec].pts,
                    self.reverse_solution,
                    false,
                    &mut path,
                ) {
                    solution_closed.push(path);
                }
            }
        }
    }

    fn execute_internal(&mut self, ct: ClipType, fillrule: FillRule, use_polytrees: bool) -> bool {
        self.cliptype = ct;
        self.fillrule = fillrule;
        self.using_polytree = use_polytrees;
        self.reset();
        if ct == ClipType::NoClip {
            return true;
        }
        let mut y = match self.pop_scanline() {
            Some(v) => v,
            None => return true,
        };

        while self.succeeded {
            self.insert_local_minima_into_ael(y);
            loop {
                let e = self.pop_horz();
                if e == NONE {
                    break;
                }
                self.do_horizontal(e);
            }
            if !self.horz_seg_list.is_empty() {
                self.convert_horz_segs_to_joins();
                self.horz_seg_list.clear();
            }
            self.bot_y = y; // bot_y_ == bottom of scanbeam
            y = match self.pop_scanline() {
                Some(v) => v,
                None => break,
            };
            self.do_intersections(y);
            self.do_top_of_scanbeam(y);
            loop {
                let e = self.pop_horz();
                if e == NONE {
                    break;
                }
                self.do_horizontal(e);
            }
        }
        if self.succeeded {
            self.process_horz_joins();
        }
        self.succeeded
    }

    pub fn execute(&mut self, ct: ClipType, fillrule: FillRule, closed: &mut Paths64) -> bool {
        closed.clear();
        if self.execute_internal(ct, fillrule, false) {
            self.build_paths(closed, None);
        }
        self.succeeded
    }

    pub fn set_preserve_collinear(&mut self, val: bool) {
        self.preserve_collinear = val;
    }
    pub fn set_reverse_solution(&mut self, val: bool) {
        self.reverse_solution = val;
    }
}

