pub fn boolean_op(
    cliptype: ClipType,
    fillrule: FillRule,
    subjects: &[Path64],
    clips: &[Path64],
) -> Paths64 {
    let mut c = Clipper::new();
    c.add_paths(subjects, PathType::Subject, false);
    c.add_paths(clips, PathType::Clip, false);
    let mut solution = Vec::new();
    c.execute(cliptype, fillrule, &mut solution);
    solution
}

pub fn union_paths(subjects: &[Path64], fillrule: FillRule) -> Paths64 {
    let mut c = Clipper::new();
    c.add_paths(subjects, PathType::Subject, false);
    let mut solution = Vec::new();
    c.execute(ClipType::Union, fillrule, &mut solution);
    solution
}

pub fn intersect(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Intersection, fillrule, subjects, clips)
}

pub fn difference(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Difference, fillrule, subjects, clips)
}

pub fn xor_paths(subjects: &[Path64], clips: &[Path64], fillrule: FillRule) -> Paths64 {
    boolean_op(ClipType::Xor, fillrule, subjects, clips)
}

pub fn pts_really_close(pt1: Point64, pt2: Point64) -> bool {
    (pt1.x - pt2.x).abs() < 2 && (pt1.y - pt2.y).abs() < 2
}

