fn parse_paths(lines: &[String], idx: &mut usize) -> Paths64 {
    let hdr: Vec<&str> = lines[*idx].split_whitespace().collect();
    assert_eq!(hdr[0], "PATHS", "expected PATHS at line {}: {}", idx, lines[*idx]);
    let n: usize = hdr[1].parse().unwrap();
    *idx += 1;
    let mut out = Vec::new();
    for _ in 0..n {
        let t: Vec<&str> = lines[*idx].split_whitespace().collect();
        assert_eq!(t[0], "P");
        let m: usize = t[1].parse().unwrap();
        let mut p = Vec::with_capacity(m);
        for k in 0..m {
            let x: i64 = t[2 + 2 * k].parse().unwrap();
            let y: i64 = t[3 + 2 * k].parse().unwrap();
            p.push(Point64::new(x, y));
        }
        out.push(p);
        *idx += 1;
    }
    out
}

fn canon(paths: &Paths64) -> Vec<Vec<(i64,i64)>> {
    let mut v: Vec<Vec<(i64,i64)>> = paths.iter().map(|p| {
        // rotate to lexicographically smallest rotation for order-insensitive compare
        let n = p.len();
        if n == 0 { return Vec::new(); }
        let mut best = 0;
        for i in 1..n {
            for k in 0..n {
                let a = p[(best + k) % n]; let b = p[(i + k) % n];
                if (b.x, b.y) < (a.x, a.y) { best = i; break; }
                if (b.x, b.y) > (a.x, a.y) { break; }
            }
        }
        (0..n).map(|k| { let q = p[(best + k) % n]; (q.x, q.y) }).collect()
    }).collect();
    v.sort();
    v
}

fn fr(v: i32) -> FillRule {
    match v { 0 => FillRule::EvenOdd, 1 => FillRule::NonZero, 2 => FillRule::Positive, _ => FillRule::Negative }
}

